window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[9]=[{"id":"09_19","g":9,"l":19,"topic":"Зарплата: начислено и на руки, ИПН и пенсионные взносы","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет рассчитать зарплату на руки из начисленной суммы с учётом ОПВ 10% и ИПН 10% с базовым вычетом 30 МРП.","criteria":["Я объясняю, чем начисленная зарплата отличается от зарплаты на руки.","Я правильно рассчитываю ОПВ, ИПН с учётом вычета и сумму на руки.","Я объясняю, на что идут пенсионные взносы и налоги и почему «серая» зарплата невыгодна работнику."],"result":"Расчётный лист условного работника: начислено, ОПВ, вычет, ИПН, на руки, плюс ОПВР, который платит работодатель.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Зарплата (salary)","real":"Оплата труда работника по трудовому договору","shown":"Оплата труда работника по трудовому договору","truth":true,"first":"З"},{"term":"Начисленная зарплата","real":"Сумма, указанная в договоре до удержаний","shown":"Индивидуальный подоходный налог, 10% от облагаемого дохода","truth":false,"first":"Н"},{"term":"Зарплата на руки","real":"Сумма, которую работник получает после удержаний","shown":"Сумма, которую работник получает после удержаний","truth":true,"first":"З"},{"term":"ОПВ","real":"Обязательные пенсионные взносы, 10% от зарплаты, удерживаются из зарплаты работника и идут на его пенсионный (pension) счёт в ЕНПФ","shown":"Сумма, указанная в договоре до удержаний","truth":false,"first":"О"},{"term":"ОПВР","real":"Обязательные пенсионные взносы работодателя, 3,5%, платятся за счёт работодателя сверх зарплаты","shown":"Обязательные пенсионные взносы работодателя, 3,5%, платятся за счёт работодателя сверх зарплаты","truth":true,"first":"О"},{"term":"ИПН","real":"Индивидуальный подоходный налог, 10% от облагаемого дохода","shown":"Обязательные пенсионные взносы, 10% от зарплаты, удерживаются из зарплаты работника и идут на его пенсионный (pension) счёт в ЕНПФ","truth":false,"first":"И"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Зарплата (salary)","def":"Оплата труда работника по трудовому договору"},{"term":"Начисленная зарплата","def":"Сумма, указанная в договоре до удержаний"},{"term":"Зарплата на руки","def":"Сумма, которую работник получает после удержаний"},{"term":"ОПВ","def":"Обязательные пенсионные взносы, 10% от зарплаты, удерживаются из зарплаты работника и идут на его пенсионный (pension) счёт в ЕНПФ"},{"term":"ОПВР","def":"Обязательные пенсионные взносы работодателя, 3,5%, платятся за счёт работодателя сверх зарплаты"},{"term":"ИПН","def":"Индивидуальный подоходный налог, 10% от облагаемого дохода"},{"term":"Базовый вычет","def":"30 МРП в месяц (30 × 4 325 = 129 750 тенге), сумма, с которой ИПН не берётся"}],"english":"pension — пенсия; salary — зарплата; money — деньги","concepts":{"head":"Определения","items":["Зарплата (salary) в договоре — начисленная.","Работодатель удерживает из неё ОПВ (10%) и ИПН (10%).","Деньги (money) на руки — остаток.","Работодатель ещё платит ОПВР 3,5% за свой счёт, на руки работника это не влияет.","В 2026 году МРП — 4 325 тенге, базовый вычет — 30 МРП = 129 750 тенге в месяц.","В учебной модели учитываем только ОПВ и ИПН."]},"steps":{"head":"Как считать, по шагам","items":["ОПВ = начислено × 10%","Облагаемый доход = начислено − ОПВ − 129 750. Если получилось меньше нуля, ИПН = 0","ИПН = облагаемый доход × 10%","На руки = начислено − ОПВ − ИПН","ОПВР = начислено × 3,5% (платит работодатель)"]},"scheme":"«Начислено» → стрелка «−ОПВ 10% → пенсионный счёт» → стрелка «−вычет 129 750 → облагаемая часть → ИПН 10% → бюджет» → «На руки». Сбоку: «ОПВР 3,5% — сверху, платит работодатель».","examples":[{"lab":"Казахстанский","text":"Продавец в Караганде, начислено 200 000 тенге. ОПВ = 20 000; облагаемый доход = 200 000 − 20 000 − 129 750 = 50 250; ИПН = 5 025; на руки = 174 975 тенге; ОПВР = 7 000."},{"lab":"Второй пример","text":"Начислено 140 000. ОПВ = 14 000; 140 000 − 14 000 − 129 750 < 0, значит ИПН = 0; на руки 126 000 тенге."}],"mistake":{"myth":"Считать ИПН от всей начисленной суммы без вычета и ОПВ","fix":"От 200 000 получилось бы 20 000 вместо 5 025."},"check":[{"q":"С какой суммы считается ИПН?","a":"Начислено минус ОПВ минус вычет"},{"q":"Чьи деньги ОПВ?","a":"Работника, они копятся на его счёте"},{"q":"Уменьшает ли ОПВР зарплату на руки?","a":"Нет"}],"kz":{"text":"ЕНПФ — Единый накопительный пенсионный фонд Казахстана, куда поступают ОПВ всех работников; каждый может проверить свои накопления через приложение ЕНПФ или eGov.kz.","link":"10% зарплаты не пропадают, а копятся на личном счёте к пенсионному возрасту 63 года для мужчин и 61 для женщин."},"world":{"text":"Во многих странах работники получают расчётный лист (payslip), где видно начисление и каждое удержание, — это требование прозрачности, связанное с ЦУР ООН 8 «Достойная работа и экономический рост».","link":""},"fact":"По распространённой версии английское слово salary происходит от латинского salarium, связанного с солью (sal), которая в Древнем Риме была ценным товаром. Историки спорят, платили ли легионерам именно солью, но связь слов признаётся словарями.","cards":[{"n":"1","title":"Расчётный лист","lines":["Вычет: 30 МРП = 129 750 тенге. ОПВ 10%, ИПН 10%, ОПВР 3,5% (платит работодатель).","Работник А: бариста, начислено 180 000 тенге.","Работник Б: менеджер по продажам, начислено 300 000 тенге.","Работник В: стажёр, начислено 120 000 тенге.","Для каждого заполните: ОПВ; облагаемый доход; ИПН; на руки; ОПВР.","Ответы для тренера: А — ОПВ 18 000, облагаемый 32 250, ИПН 3 225, на руки 158 775, ОПВР 6 300; Б — ОПВ 30 000, облагаемый 140 250, ИПН 14 025, на руки 255 975, ОПВР 10 500; В — ОПВ 12 000, ИПН 0, на руки 108 000, ОПВР 4 200."],"hand":"Сдать: таблицу из трёх строк.","answers":[]},{"n":"2","title":"Зарплата в конверте","lines":["Ситуация: Ерлану предлагают работу курьером: «Официально оформим на 120 000, остальные 130 000 дадим наличными без документов».","Вопросы: 1) Сколько ОПВ в месяц поступит на его пенсионный счёт при таком варианте и при официальных 250 000? 2) Что Ерлан теряет при «конверте»? 3) Как вежливо задать вопрос работодателю об официальной зарплате?","Олимпиадная задача: начислено 250 000 тенге. Найдите зарплату на руки."],"hand":"Сдать: ответы на 3 вопроса и решение задачи.","answers":[["","ОПВ 25 000; облагаемый доход 250 000 − 25 000 − 129 750 = 95 250; ИПН 9 525; на руки 215 475 тенге."]]}],"homework":"Рассчитай зарплату на руки для начисленных сумм 150 000, 250 000 и 400 000 условных тенге по шагам урока. Объясни в 2 предложениях, почему у суммы 150 000 ИПН получился маленьким.","support":"Шаблон расчётного листа с подсказками в каждой строке; готовое значение вычета 129 750 тенге; пример с зарплатой 200 000 как образец.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: сколько всего тратит работодатель на работника с начислением 300 000 тенге с учётом ОПВР?","photo":{"src":"lessons/img/09_19.jpg","author":"StellrWeb","q":["Что вы видите на фото? Как это связано с нашей темой?","Зачем работнику знать, сколько из его зарплаты ушло на налоги и пенсию, а не только сумму на руки?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l19.pptx","name":"19. Зарплата — начислено и на руки, ИПН и пенсионные взносы (9 кл).pptx","mb":1.3}},{"id":"09_20","g":9,"l":20,"topic":"Первая работа: трудовой договор и права подростка","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет назвать не менее 5 обязательных условий трудового договора и объяснить, сколько часов в неделю и на каких условиях может работать подросток в Казахстане.","criteria":["Я называю обязательные пункты трудового договора.","Я объясняю, сколько часов и в каких условиях может работать подросток 14–17 лет.","Я нахожу в примере договора нарушения и предлагаю, как вежливо попросить их исправить."],"result":"Чек-лист «Мой первый трудовой договор»: 5–7 обязательных пунктов и ограничения для работника до 18 лет, проверенные на примере договора.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Трудовой договор (contract)","real":"Письменное соглашение работника и работодателя об условиях работы и оплаты","shown":"Письменное соглашение работника и работодателя об условиях работы и оплаты","truth":true,"first":"Т"},{"term":"Работодатель","real":"Организация или ИП, которые нанимают работника","shown":"Период, когда работодатель проверяет, подходит ли работник","truth":false,"first":"Р"},{"term":"Трудовая функция","real":"Работа по должности, которую выполняет работник","shown":"Работа по должности, которую выполняет работник","truth":true,"first":"Т"},{"term":"Режим рабочего времени","real":"Сколько часов и в какие дни работает сотрудник","shown":"Организация или ИП, которые нанимают работника","truth":false,"first":"Р"},{"term":"Сокращённое рабочее время","real":"Уменьшенная норма часов для работников до 18 лет","shown":"Уменьшенная норма часов для работников до 18 лет","truth":true,"first":"С"},{"term":"Испытательный срок","real":"Период, когда работодатель проверяет, подходит ли работник","shown":"Сколько часов и в какие дни работает сотрудник","truth":false,"first":"И"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Трудовой договор (contract)","def":"Письменное соглашение работника и работодателя об условиях работы и оплаты"},{"term":"Работодатель","def":"Организация или ИП, которые нанимают работника"},{"term":"Трудовая функция","def":"Работа по должности, которую выполняет работник"},{"term":"Режим рабочего времени","def":"Сколько часов и в какие дни работает сотрудник"},{"term":"Сокращённое рабочее время","def":"Уменьшенная норма часов для работников до 18 лет"},{"term":"Испытательный срок","def":"Период, когда работодатель проверяет, подходит ли работник"},{"term":"Трудовой кодекс РК","def":"Главный закон о трудовых отношениях в Казахстане"}],"english":"contract — договор; money — деньги","concepts":{"head":"Определения","items":["Трудовой договор (contract) — письменное соглашение, по которому работник выполняет работу, а работодатель платит деньги (money) и обеспечивает условия.","Без договора работник почти не защищён."]},"steps":{"head":"Как это работает","items":["Возраст. По Трудовому кодексу РК договор заключают с 16 лет; с 15 лет — с письменного согласия родителя, если подросток получает образование; с 14 лет — на лёгкую работу в свободное от учёбы время с согласия родителя","Обязательные пункты договора: стороны, должность и обязанности, место работы, дата начала и срок, режим работы и отдыха, размер и порядок оплаты, условия труда, права и обязанности сторон","Ограничения для подростков: от 14 до 16 лет — не более 24 часов в неделю, от 16 до 18 — не более 36 часов; во время учёбы — ещё меньше. Запрещены тяжёлые, вредные и ночные работы, сверхурочные"]},"scheme":"«Договор» в центре, от него 7 стрелок к обязательным пунктам; справа столбец «До 18 лет»: 24/36 часов, нет ночной работы, нет тяжёлой работы, согласие родителя.","examples":[{"lab":"Казахстанский","text":"16-летнюю Дану из Алматы берут промоутером в торговый центр на летние каникулы, 6 часов в день, 5 дней (30 часов в неделю) — это допустимо, если работа не ночная и есть договор."},{"lab":"Второй пример","text":"15-летнему подростку предлагают работать на складе по ночам грузчиком — это нарушение сразу нескольких запретов."}],"mistake":{"myth":"«Устная договорённость тоже договор»","fix":"При споре без письменного договора невозможно доказать размер оплаты и часы."},"check":[{"q":"С какого возраста можно заключить договор без согласия родителя?","a":"С 16"},{"q":"Сколько часов в неделю может работать 15-летний?","a":"Не более 24"},{"q":"Можно ли подростку работать в ночную смену?","a":"Нет"}],"kz":{"text":"Портал Enbek.kz — государственная электронная биржа труда Казахстана, где публикуются вакансии и оформляются электронные трудовые договоры.","link":"подросток видит, как выглядят реальные вакансии и какие условия указаны в объявлении."},"world":{"text":"Международная организация труда (МОТ) принимает конвенции о минимальном возрасте приёма на работу и о запрете опасного детского труда, их ратифицировали большинство стран мира, включая Казахстан. Это часть ЦУР ООН 8.7 — искоренить детский труд.","link":""},"fact":"Восьмичасовой рабочий день стал стандартом не сразу: в 1914 году Генри Форд ввёл на своих заводах 8-часовую смену и одновременно повысил оплату до 5 долларов в день, что тогда было почти вдвое выше среднего. Это помогло ему удержать работников.","cards":[{"n":"1","title":"Найди нарушения","lines":["Договор: «ИП „Кофе Тайм“ принимает Нурлана (15 лет) бариста. Работа с 22:00 до 06:00, 6 дней в неделю. Оплата — по договорённости. Согласие родителей не требуется. Сверхурочная работа в выходные — по требованию».","Задание: найдите не менее 5 нарушений или пропущенных пунктов и запишите, как их исправить."],"hand":"Сдать: таблицу «нарушение — как исправить».","answers":[["Тренеру","Ночная работа; 48 часов в неделю при норме 24; нет суммы оплаты; нет согласия родителя для 15 лет; сверхурочные запрещены; нет даты начала и срока."]]},{"n":"2","title":"Считаем часы и оплату","lines":["Ситуация: Аружан 16 лет, летом она работает помощником в книжном магазине 6 часов в день, 5 дней в неделю, оплата 1 500 условных тенге в час.","1) Сколько часов в неделю она работает и укладывается ли в норму 36 часов?","2) Сколько она заработает за 4 недели (начислено)?","Олимпиадная задача: подростку 15 лет предлагают 5 смен по 6 часов в неделю. Сколько часов нужно убрать, чтобы соблюсти закон?"],"hand":"Сдать: ответы с расчётом.","answers":[["","30 − 24 = 6 часов, то есть одну смену."],["","30 часов, укладывается; 30 × 4 × 1 500 = 180 000 тенге."]]},{"n":"3","title":"Роли для презентации","lines":["«Работодатель»: торопит подписать договор, отвечает коротко.","«Подросток»: вежливо задаёт 3 вопроса по найденным нарушениям."],"hand":"Сдать: не нужно.","answers":[]}],"homework":"Найди 2 объявления о вакансиях для подростков (без личных данных) и проверь по чек-листу, каких пунктов договора в них не хватает. Составь 3 вежливых вопроса работодателю.","support":"Чек-лист с перечнем обязательных пунктов, который нужно только сопоставить с договором; подсказка с нормами часов по возрасту.","advanced":"Олимпиадная задача из Карточки 2 и задание переписать договор из Карточки 1 так, чтобы он стал законным.","photo":{"src":"lessons/img/09_20.jpg","author":"Scott Graham","q":["Что вы видите на фото? Как это связано с нашей темой?","Чем отличается безопасная подработка подростка от детского труда?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l20.pptx","name":"20. Первая работа — трудовой договор и права подростка (9 кл).pptx","mb":1.4}},{"id":"09_21","g":9,"l":21,"topic":"Сложный процент и депозиты: капитализация и гарантия КФГД","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет рассчитать сумму вклада с ежегодной капитализацией за 3 года и объяснить, как работает гарантия КФГД по сберегательным вкладам в тенге.","criteria":["Я объясняю разницу между простым и сложным процентом.","Я правильно рассчитываю сумму вклада с капитализацией за 3 года.","Я объясняю, что такое гарантия КФГД и как она защищает вкладчика."],"result":"Расчёт «Мой вклад на 3 года»: таблица по годам с капитализацией и без неё, сравнение и вывод о защите вклада гарантией КФГД.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Вклад, депозит (deposit)","real":"Деньги, которые человек размещает в банке на время и получает за это вознаграждение","shown":"Деньги, которые человек размещает в банке на время и получает за это вознаграждение","truth":true,"first":"В"},{"term":"Процент (percent)","real":"Вознаграждение банка, выраженное в долях от суммы вклада за год","shown":"Казахстанский фонд гарантирования депозитов, который возвращает вкладчику деньги, если у банка отзовут лицензию","truth":false,"first":"П"},{"term":"Простой процент","real":"Проценты каждый год начисляются только на первоначальную сумму","shown":"Проценты каждый год начисляются только на первоначальную сумму","truth":true,"first":"П"},{"term":"Сложный процент","real":"Проценты начисляются и на уже начисленные проценты","shown":"Вознаграждение банка, выраженное в долях от суммы вклада за год","truth":false,"first":"С"},{"term":"Капитализация","real":"Добавление начисленных процентов к сумме вклада","shown":"Добавление начисленных процентов к сумме вклада","truth":true,"first":"К"},{"term":"КФГД","real":"Казахстанский фонд гарантирования депозитов, который возвращает вкладчику деньги, если у банка отзовут лицензию","shown":"Проценты начисляются и на уже начисленные проценты","truth":false,"first":"К"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Вклад, депозит (deposit)","def":"Деньги, которые человек размещает в банке на время и получает за это вознаграждение"},{"term":"Процент (percent)","def":"Вознаграждение банка, выраженное в долях от суммы вклада за год"},{"term":"Простой процент","def":"Проценты каждый год начисляются только на первоначальную сумму"},{"term":"Сложный процент","def":"Проценты начисляются и на уже начисленные проценты"},{"term":"Капитализация","def":"Добавление начисленных процентов к сумме вклада"},{"term":"КФГД","def":"Казахстанский фонд гарантирования депозитов, который возвращает вкладчику деньги, если у банка отзовут лицензию"},{"term":"Гарантийное возмещение","def":"Сумма, которую КФГД выплачивает вкладчику"}],"english":"percent — процент; deposit — вклад; money — деньги","concepts":{"head":"Определения","items":["Депозит (deposit) — деньги (money) в банке под процент (percent).","Простой процент начисляется только на первоначальную сумму.","Сложный процент — с капитализацией: проценты добавляются к вкладу, и в следующем году доход считается уже от большей суммы."]},"steps":{"head":"Как это работает","items":["Записываем сумму и условную ставку","Простой процент: итог = S × (1 + r × n)","С ежегодной капитализацией: итог = S × (1 + r)ⁿ, или считаем по годам: каждый год умножаем на (1 + r)","Сравниваем","Проверяем защиту. КФГД гарантирует возврат сберегательных вкладов в тенге до 20 млн тенге на одного вкладчика в одном банке-участнике системы"]},"scheme":"«лестница» из трёх ступеней: 100 000 → ×1,12 → 112 000 → ×1,12 → 125 440 → ×1,12 → 140 493. Рядом «зонтик КФГД: до 20 млн тенге».","examples":[{"lab":"Казахстанский","text":"Школьник из Павлодара положил 100 000 условных тенге на сберегательный вклад под условные 12% годовых с ежегодной капитализацией. Год 1: 112 000; год 2: 125 440; год 3: 140 492,8 тенге. Без капитализации было бы 136 000 — разница 4 492,8 тенге."},{"lab":"Второй пример","text":"У семьи-героя задачи 25 млн тенге на сберегательном вкладе в одном банке; гарантия покрывает 20 млн, оставшиеся 5 млн защищены хуже, поэтому крупные суммы делят между банками."}],"mistake":{"myth":"Считать 12% × 3 = 36% и называть это сложным процентом","fix":"36% — это простой процент, сложный даёт 40,49%."},"check":[{"q":"Почему капитализация даёт больше?","a":"Проценты начисляются на проценты"},{"q":"Что делает КФГД?","a":"Возвращает вклады, если банк закрыли"},{"q":"Защищён ли вклад 30 млн полностью в одном банке?","a":"Нет, только 20 млн"}],"kz":{"text":"Казахстанский фонд гарантирования депозитов (КФГД) создан в 1999 году и защищает вклады граждан в банках второго уровня — участниках системы.","link":"на сайте kdif.kz можно проверить, входит ли банк в систему, и посчитать гарантию."},"world":{"text":"Системы гарантирования вкладов есть в большинстве стран: например, в США с 1933 года работает FDIC, созданная после массовых банкротств банков в Великую депрессию. Это связано с ЦУР ООН 8.10 — расширение доступа к финансовым услугам.","link":""},"fact":"Бенджамин Франклин завещал Бостону и Филадельфии по 1 000 фунтов с условием, что деньги будут расти под процент 200 лет; к 1990 году фонд Филадельфии вырос примерно до 2 миллионов долларов. Это знаменитый пример силы сложного процента.","cards":[{"n":"1","title":"Два вклада","lines":["Условие: 200 000 условных тенге на 3 года, условная ставка 10% годовых.","Вклад А: без капитализации (проценты выплачиваются на карту).","Вклад Б: с ежегодной капитализацией.","1) Заполните таблицу «год — сумма» для каждого вклада.","2) Найдите разницу через 3 года.","Ответы для тренера: А — 260 000 (проценты 60 000); Б — 220 000; 242 000; 266 200; разница 6 200 тенге."],"hand":"Сдать: таблицу и вывод.","answers":[]},{"n":"2","title":"Под зонтиком КФГД","lines":["Ситуация: у героя задачи 28 млн условных тенге на сберегательном вкладе в тенге в одном банке. Банк лишили лицензии.","1) Какую сумму гарантирует КФГД?","2) Какая часть не покрыта гарантией?","3) Как можно было разместить деньги, чтобы всё было под гарантией?","Олимпиадная задача: вклад 100 000 тенге под 10% годовых с ежегодной капитализацией. Какая сумма будет через 2 года?"],"hand":"Сдать: ответы с решением.","answers":[["1","20 млн тенге."],["2","8 млн тенге."],["3","Разделить между двумя банками-участниками, не более 20 млн в каждом."],["","100 000 × 1,1 × 1,1 = 121 000 тенге."]]}],"homework":"Рассчитай условный вклад 50 000 тенге под условные 10% на 3 года с капитализацией и без неё, найди разницу. Напиши 2 предложения: что проверить на сайте КФГД перед открытием вклада.","support":"Таблица по годам с подсказкой «предыдущая сумма × 1,12»; образец расчёта первого года; разрешён калькулятор.","advanced":"Олимпиадная задача из Карточки 2 и задача: за сколько лет вклад под условные 12% с капитализацией удвоится? (Примерно за 6–7 лет; проверить по годам.)","photo":{"src":"lessons/img/09_21.jpg","author":"micheile henderson","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему люди меньше боятся хранить деньги в банке, если вклады застрахованы государством?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l21.pptx","name":"21. Сложный процент и депозиты — капитализация и гарантия КФГД (9 кл).pptx","mb":1.4}},{"id":"09_22","g":9,"l":22,"topic":"Банковские продукты: карта, депозит, кредит — сравниваем условия","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет сравнить условия трёх банковских продуктов (карта, депозит, кредит) по ставке, комиссиям и рискам и обоснованно выбрать выгодный для заданной ситуации.","criteria":["Я объясняю, для чего нужны карта, депозит и кредит.","Я сравниваю продукты по ставке, комиссиям, сроку и рискам в таблице.","Я выбираю продукт для ситуации и обосновываю выбор цифрами."],"result":"Сравнительная таблица трёх банковских продуктов с выбором и обоснованием для ситуации героя кейса.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Банк (bank)","real":"Коммерческая финансовая организация, которая хранит деньги клиентов, выдаёт кредиты и проводит платежи, зарабатывая на этом прибыль","shown":"Коммерческая финансовая организация, которая хранит деньги клиентов, выдаёт кредиты и проводит платежи, зарабатывая на этом прибыль","truth":true,"first":"Б"},{"term":"Некоммерческая организация (non-profit)","real":"Организация, которая не ставит целью получение прибыли, например благотворительный фонд","shown":"Годовая эффективная ставка вознаграждения, показывает полную стоимость кредита или реальную доходность вклада с учётом условий","truth":false,"first":"Н"},{"term":"Дебетовая карта","real":"Карта для оплаты своими деньгами со счёта","shown":"Карта для оплаты своими деньгами со счёта","truth":true,"first":"Д"},{"term":"Депозит, вклад (deposit)","real":"Деньги в банке на срок под вознаграждение","shown":"Организация, которая не ставит целью получение прибыли, например благотворительный фонд","truth":false,"first":"Д"},{"term":"Кредит (loan)","real":"Деньги банка, которые клиент берёт и возвращает с вознаграждением","shown":"Деньги банка, которые клиент берёт и возвращает с вознаграждением","truth":true,"first":"К"},{"term":"ГЭСВ","real":"Годовая эффективная ставка вознаграждения, показывает полную стоимость кредита или реальную доходность вклада с учётом условий","shown":"Деньги в банке на срок под вознаграждение","truth":false,"first":"Г"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Банк (bank)","def":"Коммерческая финансовая организация, которая хранит деньги клиентов, выдаёт кредиты и проводит платежи, зарабатывая на этом прибыль"},{"term":"Некоммерческая организация (non-profit)","def":"Организация, которая не ставит целью получение прибыли, например благотворительный фонд"},{"term":"Дебетовая карта","def":"Карта для оплаты своими деньгами со счёта"},{"term":"Депозит, вклад (deposit)","def":"Деньги в банке на срок под вознаграждение"},{"term":"Кредит (loan)","def":"Деньги банка, которые клиент берёт и возвращает с вознаграждением"},{"term":"ГЭСВ","def":"Годовая эффективная ставка вознаграждения, показывает полную стоимость кредита или реальную доходность вклада с учётом условий"},{"term":"Комиссия","def":"Плата банку за услугу"}],"english":"bank — банк; loan — кредит; deposit — вклад; non-profit — некоммерческая организация","concepts":{"head":"Определения","items":["Банк (bank) — коммерческая организация: он платит вкладчикам меньше, чем берёт с заёмщиков, и на разнице зарабатывает.","Некоммерческая организация (non-profit), например благотворительный фонд, работает не ради прибыли, поэтому её цели другие.","Три главных продукта: карта — для расчётов; депозит (deposit) — для сбережений; кредит (loan) — для покупки сейчас за счёт будущих доходов."]},"steps":{"head":"Как сравнивать, по шагам","items":["Определить цель — платить, копить или занять","Выписать условия: ставку (лучше ГЭСВ), срок, комиссии, возможность снять деньги досрочно","Посчитать итог в тенге за год","Оценить риск: гарантия КФГД для вклада, штрафы за просрочку для кредита","Выбрать"]},"scheme":"Три колонки «Карта — платить», «Депозит — копить», «Кредит — занять»; под каждой строки «ставка», «комиссии», «срок», «риск», «итог за год в тенге».","examples":[{"lab":"Казахстанский","text":"Мадина из Актобе хочет копить 10 000 условных тенге в месяц на курсы. Ей подходит сберегательный вклад с пополнением, а не кредит."},{"lab":"Второй пример","text":"Карта А без платы за обслуживание, карта Б — 500 тенге в месяц, но с кешбэком 1% на покупки. При покупках 30 000 тенге в месяц кешбэк Б = 300 тенге, это меньше платы 500 — карта А выгоднее."}],"mistake":{"myth":"Выбирать по рекламе («кешбэк до 30%!»), не посчитав комиссии","fix":"Разбираем пример с картой Б."},"check":[{"q":"Чем ГЭСВ лучше рекламной ставки?","a":"Учитывает все платежи и условия"},{"q":"Какой продукт для подушки безопасности?","a":"Вклад с возможностью снятия"},{"q":"Почему банк выдаёт кредиты под больший процент, чем платит по вкладам?","a":"На разнице он зарабатывает"}],"kz":{"text":"Kaspi.kz — казахстанская компания, которая объединила в одном приложении платежи, маркетплейс и банковские продукты; в январе 2024 года её акции начали торговаться на бирже Nasdaq.","link":"в одном приложении клиент видит карту, депозит и кредит, и важно уметь сравнивать их условия, а не выбирать по привычке."},"world":{"text":"Банк Grameen в Бангладеш, основанный Мухаммадом Юнусом, выдавал небольшие займы бедным людям без залога; в 2006 году Юнус и банк получили Нобелевскую премию мира. Это связано с ЦУР ООН 1 «Ликвидация нищеты» и 8.10 «Доступ к финансовым услугам».","link":""},"fact":"Первая универсальная платёжная карта Diners Club появилась в 1950 году: по легенде, её создатель Фрэнк Макнамара забыл кошелёк в ресторане. Сначала карту принимали только около двух десятков ресторанов Нью-Йорка.","cards":[{"n":"1","title":"Три банка — один выбор","lines":["Герой: Тимур, 17 лет, подрабатывает и хочет за год накопить 120 000 условных тенге на ноутбук, откладывая 10 000 в месяц.","Банк «Альфа»: сберегательный вклад, условная ставка 12% годовых, без снятия до конца срока, гарантия КФГД.","Банк «Бета»: накопительный счёт, условная ставка 9%, снимать можно в любой момент без комиссии.","Банк «Гамма»: кредит 120 000 тенге сразу, вернуть 132 000 тенге за год.","Задание: заполните таблицу (цель продукта, ставка, комиссии, риск, итог в тенге) и выберите, что подходит Тимуру."],"hand":"Сдать: таблицу и вывод в 2 предложениях.","answers":[]},{"n":"2","title":"Карта с кешбэком","lines":["Карта 1: обслуживание бесплатно, кешбэка нет. Карта 2: 700 условных тенге в месяц, кешбэк 2% на все покупки.","1) Какая карта выгоднее при покупках 25 000 тенге в месяц? 2) А при 50 000?","Олимпиадная задача: при каких ежемесячных покупках выгоды карт равны?"],"hand":"Сдать: решение.","answers":[["","2% × X = 700, X = 35 000 тенге; при покупках больше 35 000 выгоднее карта 2."],["","При 25 000 кешбэк 500 < 700 — выгоднее карта 1; при 50 000 кешбэк 1 000 > 700 — выгоднее карта 2."]]}],"homework":"Выбери одну цель (копить, платить, занять) и составь список из 5 вопросов, которые нужно задать банку перед оформлением продукта. Объясни, почему важен каждый вопрос.","support":"Готовая таблица сравнения с выделенными строками «плата за год» и «доход за год»; подсказка формулы «сумма × ставка».","advanced":"Олимпиадная задача из Карточки 2 и вопрос: при каком объёме покупок в месяц карта Б из теории станет выгоднее карты А?","photo":{"src":"lessons/img/09_22.jpg","author":"Stephen Phillips","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему доступ к банковским продуктам помогает людям начать своё дело?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l22.pptx","name":"22. Банковские продукты — карта, депозит, кредит — сравниваем условия (9 кл).pptx","mb":1.5}},{"id":"09_23","g":9,"l":23,"topic":"Кредиты и долговая нагрузка","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет рассчитать переплату по кредиту и долговую нагрузку в процентах от дохода и сделать вывод, безопасен ли кредит для заёмщика.","criteria":["Я объясняю, что такое переплата и долговая нагрузка.","Я правильно рассчитываю переплату и долю платежей в доходе.","Я делаю обоснованный вывод, безопасен ли кредит, и предлагаю альтернативу."],"result":"Карта решения по кредиту: расчёт переплаты, ежемесячного платежа как доли дохода и вывод «брать / не брать / изменить условия».","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Кредит (loan)","real":"Деньги, взятые в долг у банка или МФО, которые нужно вернуть с вознаграждением","shown":"Деньги, взятые в долг у банка или МФО, которые нужно вернуть с вознаграждением","truth":true,"first":"К"},{"term":"Основной долг","real":"Сумма, которую человек взял в долг","shown":"Неуплата платежа вовремя, за которую начисляют пеню и портится кредитная история","truth":false,"first":"О"},{"term":"Переплата","real":"Разница между тем, сколько всего вернули, и суммой кредита","shown":"Разница между тем, сколько всего вернули, и суммой кредита","truth":true,"first":"П"},{"term":"Ежемесячный платёж","real":"Сумма, которую заёмщик платит каждый месяц","shown":"Сумма, которую человек взял в долг","truth":false,"first":"Е"},{"term":"Долговая нагрузка","real":"Доля дохода, которая уходит на платежи по всем кредитам","shown":"Доля дохода, которая уходит на платежи по всем кредитам","truth":true,"first":"Д"},{"term":"Просрочка","real":"Неуплата платежа вовремя, за которую начисляют пеню и портится кредитная история","shown":"Сумма, которую заёмщик платит каждый месяц","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Кредит (loan)","def":"Деньги, взятые в долг у банка или МФО, которые нужно вернуть с вознаграждением"},{"term":"Основной долг","def":"Сумма, которую человек взял в долг"},{"term":"Переплата","def":"Разница между тем, сколько всего вернули, и суммой кредита"},{"term":"Ежемесячный платёж","def":"Сумма, которую заёмщик платит каждый месяц"},{"term":"Долговая нагрузка","def":"Доля дохода, которая уходит на платежи по всем кредитам"},{"term":"Просрочка","def":"Неуплата платежа вовремя, за которую начисляют пеню и портится кредитная история"},{"term":"Кредитная история","def":"Запись о том, как человек брал и возвращал кредиты"}],"english":"loan — кредит; money — деньги","concepts":{"head":"Определения","items":["Кредит (loan) — деньги (money) в долг с возвратом и вознаграждением.","Переплата — сколько заёмщик отдал сверх суммы кредита.","Долговая нагрузка — какую часть ежемесячного дохода «съедают» платежи."]},"steps":{"head":"Как считать, по шагам","items":["Всего выплачено = ежемесячный платёж × число месяцев","Переплата = всего выплачено − сумма кредита","Переплата в % = переплата ÷ сумма кредита × 100%","Долговая нагрузка = сумма всех ежемесячных платежей ÷ ежемесячный доход × 100%","Вывод. В учебных задачах используем ориентир: если платежи забирают больше трети дохода, кредит становится опасным, — на жизнь и непредвиденные расходы остаётся мало"]},"scheme":"Весы. Слева «доход 150 000», справа гири «платёж 28 500», «жильё», «еда», «транспорт»; сверху формулы переплаты и нагрузки, шкала «до трети — допустимо, больше — опасно».","examples":[{"lab":"Казахстанский","text":"Молодой мастер из Костаная берёт в кредит инструменты на 300 000 условных тенге на 12 месяцев с платежом 28 500 тенге. Всего выплатит 342 000, переплата 42 000 тенге (14%). Его доход 150 000 тенге, нагрузка 28 500 ÷ 150 000 = 19%."},{"lab":"Второй пример","text":"У человека два кредита с платежами 40 000 и 35 000 при доходе 180 000; нагрузка 75 000 ÷ 180 000 ≈ 42% — это уже риск."}],"mistake":{"myth":"Смотреть только на «маленький платёж в месяц» и не считать переплату","fix":"Платёж 15 000 на 36 месяцев за товар 360 000 даёт 540 000, переплата 180 000."},"check":[{"q":"Как найти переплату?","a":"Всего выплачено минус кредит"},{"q":"Почему опасно брать новый кредит, чтобы закрыть старый?","a":"Нагрузка и переплата растут"},{"q":"Что увеличивает переплату — короткий или длинный срок при той же ставке?","a":"Длинный"}],"kz":{"text":"Агентство РК по регулированию и развитию финансового рынка (АРРФР) регулирует банки и микрофинансовые организации и ввело для них правило оценивать долговую нагрузку заёмщика перед выдачей кредита.","link":"государство считает долговую нагрузку важным показателем безопасности."},"world":{"text":"Глобальная проблема закредитованности домохозяйств обсуждается во многих странах; Всемирный банк и ОЭСР продвигают программы финансовой грамотности, чтобы люди считали долговую нагрузку до получения кредита. Это связано с ЦУР ООН 1 и 8.","link":""},"fact":"Одна из древнейших известных систем законов о долгах — Кодекс Хаммурапи (около XVIII века до н. э.) — уже ограничивал проценты по займам зерном и серебром. То есть правила для кредитов появились почти четыре тысячи лет назад.","cards":[{"n":"1","title":"Три заёмщика","lines":["Аня: доход 160 000, кредит 240 000 на 12 месяцев, платёж 22 500.","Болат: доход 200 000, кредит 500 000 на 24 месяца, платёж 26 000, есть ещё кредит с платежом 50 000.","Сабина: доход 120 000, кредит 180 000 на 6 месяцев, платёж 33 000.","Для каждого найдите: всего выплачено, переплату, переплату в %, долговую нагрузку в %, вывод.","Ответы для тренера: Аня — 270 000, переплата 30 000 (12,5%), нагрузка ≈ 14% — безопасно. Болат — 624 000, переплата 124 000 (24,8%), нагрузка (26 000 + 50 000) ÷ 200 000 = 38% — опасно. Сабина — 198 000, переплата 18 000 (10%), нагрузка 27,5% — допустимо, но запас мал."],"hand":"Сдать: таблицу.","answers":[]},{"n":"2","title":"Кредит за друга","lines":["Ситуация: друг просит Даурена оформить на себя кредит 200 000 тенге «для него» и обещает платить сам.","Вопросы: 1) Кто отвечает перед банком? 2) Что будет с кредитной историей Даурена при просрочке? 3) Как вежливо отказать?","Олимпиадная задача: кредит 100 000 тенге, платёж 9 500 тенге в месяц в течение 12 месяцев. Найдите переплату."],"hand":"Сдать: ответы и решение.","answers":[["","9 500 × 12 = 114 000; переплата 14 000 тенге."]]}],"homework":"Придумай условного героя с доходом и одной целью покупки. Рассчитай два варианта: кредит на 12 и на 24 месяца (платежи задай сам: 30 000 и 17 000 тенге за товар 300 000). Найди переплату и нагрузку, выбери вариант и объясни.","support":"Шаблон расчёта с формулами в строках; пример с инструментами как образец; подсказка «треть дохода = доход ÷ 3».","advanced":"Олимпиадная задача из Карточки 2 и вопрос: каким должен быть доход, чтобы платёж 45 000 тенге не превышал трети дохода? (Не меньше 135 000 тенге.)","photo":{"src":"lessons/img/09_23.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему лёгкий доступ к кредитам через приложение может быть и плюсом, и риском?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l23.pptx","name":"23. Кредиты и долговая нагрузка (9 кл).pptx","mb":1.4}},{"id":"09_24","g":9,"l":24,"topic":"Страхование: что защищает и сколько стоит","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет сравнить два страховых полиса по цене, сумме покрытия, франшизе и исключениям и выбрать подходящий для ситуации.","criteria":["Я объясняю, как работает страхование и зачем оно нужно.","Я сравниваю 2 полиса по цене, покрытию, франшизе и исключениям.","Я делаю выбор на основе расчёта, а не эмоций, и объясняю его."],"result":"Сравнительная таблица двух страховок с расчётом «цена защиты» и обоснованным выбором.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Страхование (insurance)","real":"Способ защититься от больших потерь, заплатив заранее небольшую сумму страховой компании","shown":"Способ защититься от больших потерь, заплатив заранее небольшую сумму страховой компании","truth":true,"first":"С"},{"term":"Страховой полис","real":"Документ, подтверждающий договор страхования","shown":"Часть ущерба, которую клиент оплачивает сам","truth":false,"first":"С"},{"term":"Страховая премия","real":"Сколько клиент платит за страховку","shown":"Сколько клиент платит за страховку","truth":true,"first":"С"},{"term":"Страховая сумма","real":"Максимальная сумма, которую компания выплатит","shown":"Документ, подтверждающий договор страхования","truth":false,"first":"С"},{"term":"Страховой случай","real":"Событие, при котором компания обязана платить","shown":"Событие, при котором компания обязана платить","truth":true,"first":"С"},{"term":"Франшиза","real":"Часть ущерба, которую клиент оплачивает сам","shown":"Максимальная сумма, которую компания выплатит","truth":false,"first":"Ф"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Страхование (insurance)","def":"Способ защититься от больших потерь, заплатив заранее небольшую сумму страховой компании"},{"term":"Страховой полис","def":"Документ, подтверждающий договор страхования"},{"term":"Страховая премия","def":"Сколько клиент платит за страховку"},{"term":"Страховая сумма","def":"Максимальная сумма, которую компания выплатит"},{"term":"Страховой случай","def":"Событие, при котором компания обязана платить"},{"term":"Франшиза","def":"Часть ущерба, которую клиент оплачивает сам"},{"term":"Исключения","def":"Случаи, которые страховка не покрывает"}],"english":"insurance — страхование; emotions — эмоции; money — деньги","concepts":{"head":"Определения","items":["Страхование (insurance) — договор: клиент платит премию, а страховая компания при страховом случае возмещает ущерб в пределах страховой суммы.","Компания собирает деньги (money) многих клиентов, а платит тем немногим, с кем случилась беда."]},"steps":{"head":"Как сравнивать, по шагам","items":["Что защищаем и от каких рисков","Выписываем премию, страховую сумму, франшизу, исключения","Считаем «цену защиты»: премия ÷ страховая сумма","Проверяем, покрывает ли полис наш главный риск","Принимаем решение без эмоций (emotions): страх или реклама — плохие советчики"]},"scheme":"«бассейн» — много клиентов по стрелкам вливают премии в общий фонд, из фонда одна стрелка идёт к клиенту со страховым случаем. Рядом таблица сравнения: премия, страховая сумма, франшиза, исключения, выплата в нашем случае.","examples":[{"lab":"Казахстанский","text":"В Казахстане обязательно страхование гражданско-правовой ответственности владельцев автомобилей: если водитель повредит чужую машину, ущерб оплатит страховая."},{"lab":"Второй пример","text":"Страховка телефона за 60 000 условных тенге. Полис А стоит 6 000 тенге в год, франшиза 5 000, покрывает разбитый экран и кражу. Полис Б стоит 4 000, франшиза 15 000, кражу не покрывает. При разбитом экране (ремонт 25 000) по А получим 20 000, по Б — 10 000."}],"mistake":{"myth":"Выбирать по самой низкой цене, не читая исключений","fix":"Разбираем на примере полиса Б и кражи."},"check":[{"q":"Что такое франшиза?","a":"Часть ущерба, которую платит клиент"},{"q":"Почему дешёвый полис может быть невыгоден?","a":"Высокая франшиза, много исключений"},{"q":"Зачем страховать редкие, но дорогие риски?","a":"Ущерб от них слишком велик для бюджета"}],"kz":{"text":"Обязательное страхование гражданско-правовой ответственности владельцев транспортных средств (ОГПО ВТС) действует в Казахстане, и полис должен быть у каждого владельца автомобиля.","link":"это пример, когда государство делает страховку обязательной, чтобы защитить пострадавших."},"world":{"text":"Страхование урожая от засухи помогает фермерам в Индии и странах Африки не разоряться в неурожайный год; такие программы связывают с ЦУР ООН 1 «Ликвидация нищеты» и ЦУР 13 «Борьба с изменением климата».","link":""},"fact":"Знаменитый страховой рынок Lloyd's of London начался в 1680-х годах в кофейне Эдварда Ллойда, где купцы и судовладельцы договаривались о страховании кораблей и грузов. Сегодня Lloyd's — один из крупнейших страховых рынков мира.","cards":[{"n":"1","title":"Два полиса для велосипеда","lines":["Велосипед стоит 150 000 условных тенге.","Полис «Старт»: 7 500 тенге в год, страховая сумма 150 000, франшиза 10 000, покрывает кражу и поломку при ДТП, не покрывает кражу без замка.","Полис «Эконом»: 4 500 тенге в год, страховая сумма 100 000, франшиза 25 000, покрывает только кражу.","Ситуация 1: велосипед украли с парковки (был на замке). Сколько выплатит каждый полис?","Ситуация 2: велосипед повреждён в ДТП, ремонт 40 000. Сколько выплатит каждый?","Ответы для тренера: С1 — «Старт» 140 000, «Эконом» 75 000; С2 — «Старт» 30 000, «Эконом» 0."],"hand":"Сдать: таблицу и выбор.","answers":[]},{"n":"2","title":"Честный клиент","lines":["Ситуация: знакомый предлагает «потерять» старый телефон и получить по страховке деньги на новый.","Вопросы: 1) Почему это мошенничество? 2) Как это влияет на цены страховок для всех? 3) Что ответить знакомому?","Олимпиадная задача: страховая сумма 200 000 тенге, франшиза 20 000 тенге, ущерб 90 000 тенге. Сколько выплатит страховая?"],"hand":"Сдать: ответы и решение.","answers":[["","90 000 − 20 000 = 70 000 тенге."]]}],"homework":"Выбери одну ценную вещь или событие (поездка, велосипед, ноутбук) и составь список из 5 вопросов к страховой компании перед покупкой полиса. Отметь, какой вопрос самый важный и почему.","support":"Готовая таблица сравнения; подсказка «выплата = ущерб − франшиза, если случай не в исключениях».","advanced":"Олимпиадная задача из Карточки 2 и вопрос: при каком размере ущерба полис Б из теории выплатит больше, чем А? (Никогда при одинаковом покрытии, франшиза у Б выше.)","photo":{"src":"lessons/img/09_24.jpg","author":"Erik Witsoe","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему с изменением климата страхование становится важнее для бизнеса?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l24.pptx","name":"24. Страхование — что защищает и сколько стоит (9 кл).pptx","mb":1.4}},{"id":"09_25","g":9,"l":25,"topic":"Ярмарка: личный бюджет участника","module":"Финансовая грамотность","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Работа с клиентом","Принятие решений"],"goal":"К концу урока ученик сможет составить личный бюджет участника ярмарки (план вложений, выручки и расходов) и по итогам ярмарки рассчитать свой финансовый результат.","criteria":["Я составляю план: сколько вложу, по какой цене продаю, сколько готов потратить как покупатель.","Я веду учёт каждой операции во время ярмарки.","Я считаю итог и сравниваю его с планом."],"result":"Личный бюджет участника ярмарки: план до ярмарки, учёт продаж и покупок во время ярмарки и итог «план — факт».","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Место, где продавцы и покупатели встречаются для торговли","shown":"Место, где продавцы и покупатели встречаются для торговли","truth":true,"first":"Я"},{"term":"Личный бюджет (budget)","real":"План доходов и расходов человека на период","shown":"Сумма, которую человек заранее решил не превышать","truth":false,"first":"Л"},{"term":"Выручка","real":"Все деньги, полученные от продаж","shown":"Все деньги, полученные от продаж","truth":true,"first":"В"},{"term":"Затраты","real":"Деньги, потраченные на материалы и подготовку товара","shown":"План доходов и расходов человека на период","truth":false,"first":"З"},{"term":"Прибыль","real":"Выручка минус затраты","shown":"Выручка минус затраты","truth":true,"first":"П"},{"term":"Лимит расходов","real":"Сумма, которую человек заранее решил не превышать","shown":"Деньги, потраченные на материалы и подготовку товара","truth":false,"first":"Л"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ярмарка (fair)","def":"Место, где продавцы и покупатели встречаются для торговли"},{"term":"Личный бюджет (budget)","def":"План доходов и расходов человека на период"},{"term":"Выручка","def":"Все деньги, полученные от продаж"},{"term":"Затраты","def":"Деньги, потраченные на материалы и подготовку товара"},{"term":"Прибыль","def":"Выручка минус затраты"},{"term":"Лимит расходов","def":"Сумма, которую человек заранее решил не превышать"},{"term":"«План","def":"Факт» — сравнение запланированных и реальных цифр"}],"english":"fair — ярмарка; budget — бюджет; money — деньги","concepts":{"head":"Определения","items":["Личный бюджет (budget) участника ярмарки (fair) — план, где есть вложения в товар, ожидаемая выручка, лимит расходов как покупателя и ожидаемый результат.","Деньги (money) на ярмарке — условные тенге-купоны."]},"steps":{"head":"Как это работает, по шагам","items":["Считаем затраты на товар","Ставим цену и планируем, сколько штук продадим: план выручки = цена × количество","Задаём лимит личных расходов как покупателя","На ярмарке записываем каждую продажу и покупку","После ярмарки считаем: прибыль = выручка − затраты; остаток = стартовая сумма − затраты + выручка − покупки","Сравниваем план и факт"]},"scheme":"Таблица из трёх столбцов «Статья — План — Факт»: стартовая сумма, затраты на товар, выручка, покупки, остаток; внизу «Разница: почему?».","examples":[{"lab":"Казахстанский","text":"Участник школьной ярмарки в Таразе делает 20 закладок, затраты 2 000 условных тенге, цена 300 тенге. План выручки 20 × 300 = 6 000, план прибыли 4 000. Продал 15: выручка 4 500, прибыль 2 500."},{"lab":"Второй пример","text":"Участник получил 5 000 купонов, лимит покупок 1 500, но потратил 2 800 на сладости у соседей — личный бюджет ушёл в минус относительно плана."}],"mistake":{"myth":"Считать выручку прибылью и забывать про свои покупки","fix":"Разбираем пример с закладками."},"check":[{"q":"Чем выручка отличается от прибыли?","a":"Прибыль — после вычета затрат"},{"q":"Зачем лимит расходов?","a":"Чтобы не потратить заработанное"},{"q":"Что делать, если продажи ниже плана?","a":"Менять цену, место, презентацию"}],"kz":{"text":"Базары Казахстана — от исторических торговых городов Великого шёлкового пути (Отрар, Тараз, Туркестан) до современного Зелёного базара в Алматы — пример того, как торговля веками строилась на личном контакте продавца и покупателя.","link":"каждый продавец на базаре ведёт свой бюджет и считает выручку."},"world":{"text":"Ярмарки «справедливой торговли» (Fair Trade) продают товары фермеров и мастеров из развивающихся стран по честной цене, связанной с ЦУР ООН 12 «Ответственное потребление и производство».","link":""},"fact":"Лейпцигская ярмарка в Германии считается одной из старейших в мире: город получил право проводить ярмарки около 1165 года. Позже именно там появились выставки образцов товаров, ставшие прообразом современных выставок.","cards":[{"n":"1","title":"Мой бюджет участника","lines":["Стартовая сумма: 5 000 условных тенге-купонов.","План до ярмарки: затраты на товар ___; цена за штуку ___; план продаж ___ шт.; план выручки = цена × количество ___; лимит личных покупок ___; план остатка = 5 000 − затраты + выручка − покупки ___.","Во время ярмарки: журнал «№ — продажа/покупка — сумма».","После ярмарки: факт выручки, факт покупок, прибыль = выручка − затраты, остаток, разница с планом."],"hand":"Сдать: заполненную карточку.","answers":[]},{"n":"2","title":"События рынка (тренер зачитывает одно)","lines":["1) «Покупатели устали: всё дороже 400 тенге не покупают 3 минуты».","2) «Поставщик подорожал: у кого товар закончился, докупает материалы на 20% дороже».","3) «Конкурент снизил цену: соседний ряд продаёт похожий товар на 100 тенге дешевле».","Задание для команд: за 1 минуту решите, меняете ли цену, и запишите решение в журнал."],"hand":"Сдать: запись в журнале учёта.","answers":[]}],"homework":"Перенеси свой бюджет участника в таблицу «план — факт» и напиши 3 предложения: что совпало, что нет и что изменишь на следующей ярмарке.","support":"Заполненный образец бюджета с закладками; журнал учёта с готовыми столбцами; помощь «финансиста» команды.","advanced":"Рассчитать, при какой цене участник вышел бы на плановую прибыль при фактическом количестве продаж, и предложить акцию для увеличения продаж.","photo":{"src":"lessons/img/09_25.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Готовы ли вы платить чуть больше, если знаете, что деньги честно дошли до производителя?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l25.pptx","name":"25. Ярмарка — личный бюджет участника (9 кл).pptx","mb":1.7}},{"id":"09_26","g":9,"l":26,"topic":"Финансовое мошенничество: социальная инженерия, пирамиды, дропперы","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет назвать 5 признаков финансового мошенничества по рекомендациям АРРФР, распознать их в сообщениях и объяснить, почему передача своей карты другим делает человека соучастником (дроппером).","criteria":["Я называю 5 признаков мошенничества и нахожу их в примерах.","Я объясняю, что такое социальная инженерия, пирамида и дропперство.","Я объясняю, почему передавать свою карту и коды нельзя, и знаю, что делать при подозрении."],"result":"Памятка «Стоп-мошенник»: 5 признаков, 3 разобранных сообщения с найденными признаками и алгоритм действий.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Мошенничество (fraud)","real":"Обман с целью завладеть чужими деньгами или имуществом","shown":"Обман с целью завладеть чужими деньгами или имуществом","truth":true,"first":"М"},{"term":"Социальная инженерия","real":"Приёмы, когда мошенник давит на эмоции (страх, жадность, срочность), чтобы человек сам отдал данные или деньги","shown":"Агентство РК по регулированию и развитию финансового рынка, которое выдаёт лицензии и предупреждает о мошенниках","truth":false,"first":"С"},{"term":"Финансовая пирамида","real":"Схема, где «доход» старым участникам платят из взносов новых, а не из реального бизнеса","shown":"Схема, где «доход» старым участникам платят из взносов новых, а не из реального бизнеса","truth":true,"first":"Ф"},{"term":"Дроппер","real":"Человек, через чью карту или счёт мошенники проводят украденные деньги","shown":"Приёмы, когда мошенник давит на эмоции (страх, жадность, срочность), чтобы человек сам отдал данные или деньги","truth":false,"first":"Д"},{"term":"Социальное предпринимательство (social entrepreneurship)","real":"Бизнес, который решает общественную проблему и честно отчитывается о результатах","shown":"Бизнес, который решает общественную проблему и честно отчитывается о результатах","truth":true,"first":"С"},{"term":"АРРФР","real":"Агентство РК по регулированию и развитию финансового рынка, которое выдаёт лицензии и предупреждает о мошенниках","shown":"Человек, через чью карту или счёт мошенники проводят украденные деньги","truth":false,"first":"А"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Мошенничество (fraud)","def":"Обман с целью завладеть чужими деньгами или имуществом"},{"term":"Социальная инженерия","def":"Приёмы, когда мошенник давит на эмоции (страх, жадность, срочность), чтобы человек сам отдал данные или деньги"},{"term":"Финансовая пирамида","def":"Схема, где «доход» старым участникам платят из взносов новых, а не из реального бизнеса"},{"term":"Дроппер","def":"Человек, через чью карту или счёт мошенники проводят украденные деньги"},{"term":"Социальное предпринимательство (social entrepreneurship)","def":"Бизнес, который решает общественную проблему и честно отчитывается о результатах"},{"term":"АРРФР","def":"Агентство РК по регулированию и развитию финансового рынка, которое выдаёт лицензии и предупреждает о мошенниках"}],"english":"fraud — мошенничество; finance — финансы; social entrepreneurship — социальное предпринимательство; money — деньги","concepts":{"head":"Определения","items":["Мошенничество (fraud) — обман ради чужих денег (money).","Социальная инженерия: звонок «из службы безопасности банка», сообщение «ваша карта заблокирована».","Пирамида: «вложи 50 000 — через месяц получи 100 000, приведи друзей».","Дропперство: «работа на дому — принимай переводы на свою карту и пересылай дальше за процент»."]},"steps":{"head":"Как распознать, по шагам","items":["Пять признаков по рекомендациям АРРФР: 1 — обещают высокий и гарантированный доход без риска; 2 — торопят и давят: «только сегодня», «иначе потеряете деньги»; 3 — просят коды из SMS, CVV, пароли или данные карты; 4 — платят за привлечение новых участников; 5 — нет лицензии на финансовые услуги, её можно проверить на сайте АРРФР","Алгоритм: остановиться, положить трубку, перезвонить в банк по номеру с обратной стороны карты, рассказать взрослым"]},"scheme":"«светофор»: красный — 5 признаков, жёлтый — «остановись и проверь», зелёный — «перезвони в банк, сообщи взрослым». Сбоку схема пирамиды: верх получает деньги нижних уровней.","examples":[{"lab":"Казахстанский","text":"Подростку из Усть-Каменогорска в мессенджере предлагают «подработку»: принять на карту 100 000 условных тенге и перевести дальше, оставив 5 000 себе. Это дропперство: деньги украдены, а следы ведут к его карте, и за это в Казахстане предусмотрена ответственность."},{"lab":"Второй пример","text":"«социальный проект» собирает взносы «на помощь детям» и обещает 30% в месяц вкладчикам. Настоящее социальное предпринимательство (social entrepreneurship) не обещает доходность за привлечение людей."}],"mistake":{"myth":"«Я только дал карту, я ничего не крал»","fix":"Через карту прошли украденные деньги, отвечает её владелец."},"check":[{"q":"Может ли банк попросить код из SMS?","a":"Нет"},{"q":"Почему пирамида рушится?","a":"Новых участников становится мало, платить нечем"},{"q":"Чем рискует дроппер?","a":"Становится соучастником преступления"}],"kz":{"text":"Агентство РК по регулированию и развитию финансового рынка (АРРФР) публикует на своём сайте и финансовом портале finreg.kz предупреждения о признаках мошенничества и список организаций с лицензиями.","link":"любой может проверить, имеет ли компания право принимать деньги."},"world":{"text":"Схема Чарльза Понци в США в 1920 году стала символом финансовых пирамид: он обещал 50% дохода за 45 дней и платил старым вкладчикам деньгами новых. Мошенничество в интернете — глобальная проблема, связанная с ЦУР ООН 16 «Мир, правосудие и эффективные институты».","link":""},"fact":"Чарльз Понци за несколько месяцев 1920 года собрал около 15 миллионов долларов от десятков тысяч людей, а затем схема рухнула, и он был осуждён. С тех пор подобные схемы в английском языке называют «Ponzi scheme».","cards":[{"n":"1","title":"Найди признаки","lines":["Сообщение А: «Служба безопасности банка. С вашей карты пытаются списать деньги. Срочно назовите код из SMS, иначе деньги пропадут».","Сообщение Б: «Инвестиционный клуб: вложи 50 000 условных тенге — через месяц получи 100 000! Приведи 3 друзей и получи бонус».","Сообщение В: «Подработка для школьников: принимай переводы на свою карту и отправляй дальше, 5% твои».","Сообщение Г: «Социальный фонд собирает на помощь детям. Отчёт о расходах опубликован на сайте, лицензий на приём вкладов не требуется, доход не обещаем».","Задание: для каждого отметьте признаки (1–5) и решите: мошенничество или нет."],"hand":"Сдать: таблицу. Для тренера: А — 2, 3; Б — 1, 2, 4, 5; В — дропперство, 1, 3; Г — признаков нет, но стоит проверить фонд по открытым данным.","answers":[]},{"n":"2","title":"Кейс дроппера","lines":["Ситуация: Арман, 16 лет, «одолжил» карту знакомому за 10 000 тенге. Через карту прошло 900 000 тенге украденных денег.","Вопросы: 1) Кто отвечает за операции по карте? 2) Какие последствия могут быть? 3) Что Арману сделать сейчас?","Олимпиадная задача: пирамида обещает каждому вкладчику удвоить вклад, если он приведёт 2 новых. В первом уровне 1 человек. Сколько людей должно быть на 10-м уровне?"],"hand":"Сдать: ответы и решение.","answers":[["","2⁹ = 512; на 20-м — более 500 тысяч, поэтому пирамида неизбежно рушится."]]},{"n":"3","title":"Роли для сцены","lines":["«Мошенник»: звонит от имени банка, торопит, просит код.","«Ученик»: спокойно отказывает, кладёт трубку и называет свои следующие шаги."],"hand":"Сдать: не нужно.","answers":[]}],"homework":"Расскажи одному взрослому из семьи о 5 признаках мошенничества и вместе с ним составь «семейное правило безопасности» из 3 пунктов. Запиши правило и одно наблюдение, что взрослый не знал.","support":"Список 5 признаков в виде таблички, которую можно накладывать на сообщения; подсказки-слова: «гарантия», «срочно», «код», «приведи друга», «лицензия».","advanced":"Олимпиадная задача из Карточки 2 и задание составить своё учебное «сообщение мошенника» со скрытыми признаками для другой пары.","photo":{"src":"lessons/img/09_26.jpg","author":"Hassan OUAJBIR","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему пирамиды появляются снова и снова, несмотря на известные истории краха?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l26.pptx","name":"26. Финансовое мошенничество — социальная инженерия, пирамиды, дропперы (9 кл).pptx","mb":1.3}},{"id":"09_27","g":9,"l":27,"topic":"Финансовые решения: кейсы олимпиады ФГиБ, уровень 1","module":"Финансовая грамотность","format":"Кейс-урок","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет решить 5 задач школьного этапа олимпиады по финансовой грамотности (инфляция, проценты, депозиты, мошенничество) и объяснить ход решения.","criteria":["Я выбираю нужную формулу или правило для каждой задачи.","Я записываю ход решения и получаю верный ответ.","Я понятно объясняю решение одной задачи классу."],"result":"Лист решений олимпиадного кейса: 5 задач с записанным ходом решения и ответом, плюс одна задача, объяснённая классу.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Кейс","min":12},{"stage":"Решение","min":10},{"stage":"Обсуждение","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Финансы (finance)","real":"Всё, что связано с деньгами: доходы, расходы, сбережения, долги","shown":"Всё, что связано с деньгами: доходы, расходы, сбережения, долги","truth":true,"first":"Ф"},{"term":"Инфляция","real":"Общий рост цен","shown":"Сигнал обмана: гарантированный высокий доход, срочность, просьба кодов, плата за привлечение, нет лицензии","truth":false,"first":"И"},{"term":"Сложный процент","real":"Начисление процентов на проценты","shown":"Начисление процентов на проценты","truth":true,"first":"С"},{"term":"Капитализация","real":"Добавление процентов к вкладу","shown":"Общий рост цен","truth":false,"first":"К"},{"term":"Гарантия КФГД","real":"Возврат сберегательных вкладов в тенге до 20 млн тенге на вкладчика в одном банке-участнике","shown":"Возврат сберегательных вкладов в тенге до 20 млн тенге на вкладчика в одном банке-участнике","truth":true,"first":"Г"},{"term":"Признак мошенничества","real":"Сигнал обмана: гарантированный высокий доход, срочность, просьба кодов, плата за привлечение, нет лицензии","shown":"Добавление процентов к вкладу","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Финансы (finance)","def":"Всё, что связано с деньгами: доходы, расходы, сбережения, долги"},{"term":"Инфляция","def":"Общий рост цен"},{"term":"Сложный процент","def":"Начисление процентов на проценты"},{"term":"Капитализация","def":"Добавление процентов к вкладу"},{"term":"Гарантия КФГД","def":"Возврат сберегательных вкладов в тенге до 20 млн тенге на вкладчика в одном банке-участнике"},{"term":"Признак мошенничества","def":"Сигнал обмана: гарантированный высокий доход, срочность, просьба кодов, плата за привлечение, нет лицензии"}],"english":"finance — финансы; money — деньги","concepts":{"head":"Определения","items":["Олимпиадная задача по финансам (finance) проверяет не память, а умение применить правило к ситуации с деньгами (money).","Основные инструменты: процент от числа, сложный рост (инфляция и вклады), сравнение вариантов, признаки мошенничества."]},"steps":{"head":"Как решать, по шагам","items":["Прочитать условие и подчеркнуть данные","Определить тип задачи: рост цен, вклад, сравнение, безопасность","Выбрать формулу: процент = число × p ÷ 100; рост за n лет = S × (1 + r)ⁿ; переплата = всего выплачено − долг","Посчитать и проверить здравым смыслом","Записать ответ с единицами (тенге, %)"]},"scheme":"«дерево выбора»: от вопроса «что спрашивают?» ветки «цена в будущем → (1 + i)ⁿ», «доход вклада → капитализация», «что выгоднее → считаем оба варианта», «безопасно ли → 5 признаков».","examples":[{"lab":"Казахстанский","text":"Цена школьного рюкзака 15 000 условных тенге, инфляция 6% в год. Через 2 года: 15 000 × 1,06 × 1,06 = 16 854 тенге."},{"lab":"Второй пример","text":"Вклад 50 000 тенге под условные 10% с капитализацией на 2 года: 50 000 × 1,1 × 1,1 = 60 500 тенге."}],"mistake":{"myth":"Невнимательное чтение («через 2 года» решают как «через 1 год»)","fix":"Подчёркиваем числа и слова «каждый», «через», «всего»."},"check":[{"q":"Почему при 6% за 2 года цена выросла больше чем на 12%?","a":"Сложный рост"},{"q":"Какой вклад защищён КФГД полностью: 15 млн или 25 млн тенге в одном банке?","a":"15 млн"},{"q":"Что важнее в олимпиадной задаче — ответ или решение?","a":"Оба, решение даёт баллы даже при арифметической ошибке"}],"kz":{"text":"Национальный банк Республики Казахстан и АРРФР проводят просветительские проекты по финансовой грамотности, а финансовый портал finreg.kz публикует материалы для школьников.","link":"задачи олимпиады ФГиБ основаны на реальных правилах — КФГД, налоги, признаки мошенничества."},"world":{"text":"Международное исследование PISA, которое проводит ОЭСР, с 2012 года проверяет финансовую грамотность 15-летних школьников разных стран на задачах о бюджете, процентах и рисках. Это связано с ЦУР ООН 4 «Качественное образование».","link":""},"fact":"Альберту Эйнштейну часто приписывают фразу о том, что сложный процент — «восьмое чудо света», но надёжного подтверждения, что он это говорил, нет. Это хороший пример того, почему нужно проверять источники цитат.","cards":[{"n":"1","title":"Кейс олимпиады: 5 задач","lines":["1) Инфляция. Билет в кино стоил 2 000 условных тенге. Цены 3 года росли на 5% в год. Сколько стоит билет сейчас?","2) Проценты. Магазин поднял цену на 20%, потом снизил на 20%. Товар стоил 10 000 тенге. Какой стала цена?","3) Депозит. Вклад 80 000 тенге под условные 10% годовых с ежегодной капитализацией. Какая сумма через 2 года?","4) Гарантия. У вкладчика в одном банке 22 млн тенге на сберегательном вкладе в тенге. Банк закрыли. Сколько вернёт КФГД?","5) Мошенничество. Найдите 3 признака: «Срочно! Только сегодня инвестируй 30 000 и получи гарантированно 60 000 через неделю. Пришли фото карты с двух сторон»."],"hand":"Сдать: лист решений группы.","answers":[]},{"n":"2","title":"Ключ ответов","lines":["1) 2 000 × 1,05³ = 2 315,25 ≈ 2 315 тенге. 2) 10 000 × 1,2 = 12 000; 12 000 × 0,8 = 9 600 тенге. 3) 80 000 × 1,1 × 1,1 = 96 800 тенге. 4) 20 млн тенге. 5) Срочность, гарантированный высокий доход, просьба данных карты."],"hand":"Сдать: проверенный лист другой группы с баллами (по 2 балла за задачу).","answers":[]},{"n":"3","title":"Домашние задачи","lines":["1) Цена 40 000 тенге, инфляция 8% в год. Сколько через 2 года?","2) Зарплата выросла на 6%, цены на 9%. Вырос ли реальный доход?","3) Вклад 200 000 под условные 5% с капитализацией. Сколько через 3 года?"],"hand":"Сдать: решения в тетради.","answers":[["1","46 656."],["2","Нет, упал примерно на 3%."],["3","231 525."]]}],"homework":"Реши 3 задачи из Карточки 3 и запиши ход решения. Придумай одну свою задачу на инфляцию или вклад с ответом.","support":"«Стена формул» на доске; подсказка к каждой задаче (тип задачи); работа в паре с сильным учеником.","advanced":"Задача повышенной сложности: вклад 100 000 тенге под условные 12% с капитализацией и инфляция 8%. Вырастет ли покупательная способность через 2 года? (100 000 × 1,12² = 125 440; цены × 1,08² = 1,1664; 125 440 ÷ 1,1664 ≈ 107 545 — да, примерно на 7,5%.)","photo":{"src":"lessons/img/09_27.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему страны хотят сравнивать финансовую грамотность своих подростков?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l27.pptx","name":"27. Финансовые решения — кейсы олимпиады ФГиБ, уровень 1 (9 кл).pptx","mb":1.4}},{"id":"09_28","g":9,"l":28,"topic":"После ярмарки: мой финансовый результат","module":"Финансовая грамотность","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет проанализировать свой финансовый результат ярмарки по цифрам (выручка, затраты, прибыль, «план — факт») и сформулировать 2 вывода для улучшения.","criteria":["Я правильно считаю выручку, затраты, прибыль и отклонение от плана.","Я объясняю причины расхождений, опираясь на цифры и наблюдения.","Я формулирую конкретное решение для следующей ярмарки."],"result":"Финансовый отчёт участника ярмарки: таблица «план — факт», расчёт прибыли и рентабельности, 2 вывода и 1 решение на будущее.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Учебная торговая площадка, где ученики продают и покупают за условные тенге","shown":"Учебная торговая площадка, где ученики продают и покупают за условные тенге","truth":true,"first":"Я"},{"term":"Финансовый результат","real":"Итог деятельности в деньгах: прибыль или убыток","shown":"Какая часть выручки осталась прибылью, в процентах","truth":false,"first":"Ф"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Все деньги от продаж","truth":true,"first":"В"},{"term":"Затраты","real":"Деньги на материалы и подготовку товара","shown":"Итог деятельности в деньгах: прибыль или убыток","truth":false,"first":"З"},{"term":"Прибыль","real":"Выручка минус затраты; если результат отрицательный, это убыток","shown":"Выручка минус затраты; если результат отрицательный, это убыток","truth":true,"first":"П"},{"term":"Рентабельность","real":"Какая часть выручки осталась прибылью, в процентах","shown":"Деньги на материалы и подготовку товара","truth":false,"first":"Р"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Учебная торговая площадка, где ученики продают и покупают за условные тенге"},{"term":"Финансовый результат","def":"Итог деятельности в деньгах: прибыль или убыток"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Затраты","def":"Деньги на материалы и подготовку товара"},{"term":"Прибыль","def":"Выручка минус затраты; если результат отрицательный, это убыток"},{"term":"Рентабельность","def":"Какая часть выручки осталась прибылью, в процентах"},{"term":"Отклонение","def":"Разница между фактом и планом"}],"english":"fair — ярмарка; finance — финансы; money — деньги","concepts":{"head":"Определения","items":["Финансы (finance) участника ярмарки (fair) — это его деньги (money): вложения, выручка, покупки, прибыль.","Финансовый результат = выручка − затраты.","Рентабельность продаж = прибыль ÷ выручка × 100%."]},"steps":{"head":"Как анализировать, по шагам","items":["Собрать данные из журнала учёта","Посчитать выручку, затраты, прибыль","Сравнить с планом: отклонение = факт − план","Найти причины: цена, ассортимент, место, презентация, события рынка","Принять одно решение на будущее"]},"scheme":"«лестница результата»: выручка → минус затраты → прибыль → рентабельность; справа таблица «План — Факт — Отклонение — Причина».","examples":[{"lab":"Казахстанский","text":"Команда из Кызылорды продавала браслеты. План: 25 штук по 400 условных тенге = 10 000, затраты 3 000, прибыль 7 000. Факт: 18 штук = 7 200, прибыль 4 200, отклонение −2 800. Причина: после события «конкурент снизил цену» не поменяли цену. Рентабельность: 4 200 ÷ 7 200 ≈ 58%."},{"lab":"Второй пример","text":"Команда снизила цену с 500 до 400 и продала 30 штук вместо 20: выручка 12 000 вместо 10 000 — снижение цены увеличило выручку."}],"mistake":{"myth":"Объяснять неудачу «не повезло» без цифр","fix":"Какая операция или событие дало отклонение."},"check":[{"q":"Может ли быть большая выручка и маленькая прибыль?","a":"Да, при высоких затратах"},{"q":"Что показывает отрицательное отклонение?","a":"Результат хуже плана"},{"q":"Почему важно опираться на наблюдения, а не только на цифры?","a":"Цифры показывают «что», наблюдения — «почему»"}],"kz":{"text":"Казахстанские компании, акции которых торгуются на бирже, например Kaspi.kz и Халык Банк, регулярно публикуют финансовые отчёты с выручкой и прибылью.","link":"отчёт участника ярмарки устроен по той же логике «выручка — затраты — прибыль»."},"world":{"text":"Крупные компании мира каждый квартал публикуют финансовые отчёты и сравнивают результат с прогнозом, а инвесторы оценивают, как компания объясняет отклонения. Ответственное отношение к ресурсам связано с ЦУР ООН 12.","link":""},"fact":"Одну из первых известных книг по двойной бухгалтерии опубликовал итальянский математик Лука Пачоли в 1494 году; принцип «каждая операция записывается дважды» используется до сих пор. Поэтому Пачоли называют «отцом бухгалтерии».","cards":[{"n":"1","title":"План — факт","lines":["Строки: стартовая сумма; затраты на товар; количество проданного; цена; выручка; личные покупки; прибыль = выручка − затраты; рентабельность = прибыль ÷ выручка × 100%; остаток.","Столбцы: План | Факт | Отклонение (факт − план) | Причина."],"hand":"Сдать: заполненную таблицу.","answers":[]},{"n":"2","title":"Лист наблюдений галереи","lines":["Для каждой из 3 чужих команд запишите: 1) их прибыль; 2) что они сделали иначе (цена, товар, место, общение с покупателем); 3) одну идею, которую возьмёте себе.","Вопрос для обсуждения: какая команда лучше всех отреагировала на событие рынка?"],"hand":"Сдать: лист наблюдений.","answers":[]},{"n":"3","title":"Пример для разбора","lines":["Команда «Эко-сумки»: план — 12 сумок по 800 условных тенге, затраты 4 000. Факт — 9 сумок, затраты 4 000.","Посчитайте план и факт прибыли и отклонение. (План 9 600 − 4 000 = 5 600; факт 7 200 − 4 000 = 3 200; отклонение −2 400.)"],"hand":"Сдать: расчёт и одну возможную причину.","answers":[]}],"homework":"Оформи финансовый отчёт участника: таблица «план — факт», прибыль, рентабельность, 2 вывода и 1 решение. Объём — одна страница.","support":"Таблица с заполненными формулами-подсказками; список типичных причин отклонений для выбора.","advanced":"Рассчитать, какой должна была быть цена, чтобы при фактическом объёме продаж выйти на плановую прибыль, и оценить, купили бы по такой цене.","photo":{"src":"lessons/img/09_28.jpg","author":"Alexander Mils","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему честный отчёт о неудаче полезнее, чем красивый, но неправдивый?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l28.pptx","name":"28. После ярмарки — мой финансовый результат (9 кл).pptx","mb":1.5}},{"id":"09_29","g":9,"l":29,"topic":"Проект «Мой финансовый план на год","module":"Финансовая грамотность","format":"Проектная мастерская","skills":["Финансовое мышление","Командная работа","Презентация"],"goal":"К концу урока ученик сможет составить финансовый план на год для условного героя (доходы, расходы, цели, подушка безопасности) и защитить его по критериям.","criteria":["Я составляю план с доходами, расходами и целями, где расходы не превышают доходы.","Я учитываю инфляцию, подушку безопасности и риски.","Я понятно защищаю план и отвечаю на вопросы по цифрам."],"result":"Командный проект «Финансовый план на год»: таблица доходов и расходов по месяцам, 2 цели со сроками, подушка безопасности, учёт инфляции и короткая защита.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Финансовый план (plan)","real":"Расписание доходов, расходов и накоплений на период с целями и сроками","shown":"Расписание доходов, расходов и накоплений на период с целями и сроками","truth":true,"first":"Ф"},{"term":"Проект (project)","real":"Работа с конкретным результатом и сроком","shown":"Часть дохода, которую откладывают","truth":false,"first":"П"},{"term":"Финансовая цель","real":"Конкретная сумма к конкретному сроку","shown":"Конкретная сумма к конкретному сроку","truth":true,"first":"Ф"},{"term":"Подушка безопасности","real":"Запас денег на 3–6 месяцев обязательных расходов","shown":"Работа с конкретным результатом и сроком","truth":false,"first":"П"},{"term":"Обязательные расходы","real":"Траты, без которых не обойтись","shown":"Траты, без которых не обойтись","truth":true,"first":"О"},{"term":"Сбережения","real":"Часть дохода, которую откладывают","shown":"Запас денег на 3–6 месяцев обязательных расходов","truth":false,"first":"С"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Финансовый план (plan)","def":"Расписание доходов, расходов и накоплений на период с целями и сроками"},{"term":"Проект (project)","def":"Работа с конкретным результатом и сроком"},{"term":"Финансовая цель","def":"Конкретная сумма к конкретному сроку"},{"term":"Подушка безопасности","def":"Запас денег на 3–6 месяцев обязательных расходов"},{"term":"Обязательные расходы","def":"Траты, без которых не обойтись"},{"term":"Сбережения","def":"Часть дохода, которую откладывают"},{"term":"Резерв на инфляцию","def":"Добавка к цене цели с учётом будущего подорожания"}],"english":"finance — финансы; project — проект; money — деньги; plan — план","concepts":{"head":"Определения","items":["Финансовый план (plan) — документ, где по месяцам расписаны доходы, расходы и накопления на цели.","Финансы (finance) в плане должны «сходиться»: расходы + сбережения = доходы.","Проект (project) урока — план для условного героя, деньги (money) только условные."]},"steps":{"head":"Как составить, по шагам","items":["Доходы героя (подработка, стипендия, подарки) в месяц","Обязательные и необязательные расходы","Цели SMART: сумма и срок","Подушка безопасности: обязательные расходы × 3","Ежемесячные сбережения = (цель + подушка) ÷ месяцы","Учёт инфляции: цену цели через год умножаем на (1 + инфляция)","Проверка, хватает ли денег; если нет — менять цель, срок или расходы"]},"scheme":"«пирамида плана»: внизу доходы, выше обязательные расходы, затем подушка, затем цели, наверху «желания».","examples":[{"lab":"Казахстанский","text":"Герой — Алихан, 16 лет, Атырау. Доход от подработки 60 000 условных тенге в месяц, обязательные расходы 30 000, цель — курсы программирования за 180 000 через год, инфляция 6%: 180 000 × 1,06 = 190 800. Подушка 30 000 × 3 = 90 000. Нужно откладывать (190 800 + 90 000) ÷ 12 ≈ 23 400 в месяц. На необязательное остаётся 6 600."},{"lab":"Второй пример","text":"Если цель 400 000, план не сходится — переносим срок на 2 года."}],"mistake":{"myth":"План без подушки и без инфляции","fix":"Одна поломка — и цель срывается."},"check":[{"q":"Что первым включаем в план после обязательных расходов?","a":"Подушку"},{"q":"Почему цель через год дороже?","a":"Инфляция"},{"q":"Что делать, если план не сходится?","a":"Менять срок, цель или расходы"}],"kz":{"text":"Пенсионная система Казахстана через ЕНПФ показывает пример долгосрочного финансового плана: взносы копятся десятилетиями к пенсионному возрасту 63 года для мужчин и 61 для женщин.","link":"годовой план — первый шаг к долгосрочному мышлению."},"world":{"text":"Финансовое планирование подростков — тема программ ОЭСР и ЮНИСЕФ, которые продвигают финансовую грамотность молодёжи как часть ЦУР ООН 4 «Качественное образование» и ЦУР 8.","link":""},"fact":"Бенджамин Франклин вёл ежедневные записи о делах и тратах и сформулировал правило «Пенни сбережённый — пенни заработанный», которое стало пословицей. Его «Альманах бедного Ричарда» был одним из самых читаемых изданий в Америке XVIII века.","cards":[{"n":"1","title":"Герои проекта","lines":["Герой А: Алихан, 16 лет. Доход: подработка 60 000 условных тенге в месяц. Обязательные расходы: 30 000.","Цель: курсы программирования 180 000.","Герой Б: Камила, 17 лет. Доход: 45 000 в месяц, летом (3 месяца) — 90 000. Обязательные расходы: 25 000. Цели: ноутбук 300 000 и поездка 100 000.","Герой В: Данияр, 15 лет. Доход: 20 000 в месяц + 50 000 подарков в год. Обязательные расходы: 10 000.","Цель: оборудование для мини-бизнеса 150 000.","Инфляция для всех: 6% в год."],"hand":"Сдать: план на год в таблице.","answers":[]},{"n":"2","title":"Критерии защиты","lines":["1) План сходится: расходы + сбережения = доходы в каждом месяце (3 балла).","2) Есть подушка безопасности и учтена инфляция (3 балла).","3) Цели SMART: сумма и срок (2 балла).","4) Защита: понятно, по цифрам, все участники говорят (2 балла)."],"hand":"Сдать: лист взаимооценки другой команды.","answers":[]}],"homework":"Доработай план команды по отзывам показа. Индивидуально: составь черновик своей финансовой цели на год (сумма, срок, сколько откладывать в месяц) без указания доходов семьи.","support":"Шаблон с уже заполненными строками доходов; памятка «пирамида плана»; герой с простыми цифрами (Карточка 1, герой А).","advanced":"Добавить в план сценарий риска (доход упал на 20% на 3 месяца) и показать, как подушка спасает цель.","photo":{"src":"lessons/img/09_29.jpg","author":"Eric Rothermel","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему умение планировать деньги важно для молодого человека в любой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l29.pptx","name":"29. Проект «Мой финансовый план на год» (9 кл).pptx","mb":1.5}},{"id":"09_30","g":9,"l":30,"topic":"Итоговая работа за полугодие: все разделы","module":"Все разделы","format":"Итоговая работа","skills":["Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет выполнить итоговую работу за полугодие: ответить на тестовые вопросы по всем разделам, включая финансовую грамотность, и решить практическое задание с расчётами.","criteria":["Я правильно отвечаю на тестовые вопросы по разделам полугодия.","Я решаю практическое задание с записью хода решения.","Я проверяю свою работу по чек-листу и честно оцениваю результат."],"result":"Выполненная итоговая работа: тест из 10 вопросов, практическое задание «Финансовое решение героя» и лист самопроверки.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Повторение (review)","real":"Возвращение к изученному, чтобы закрепить знания","shown":"Возвращение к изученному, чтобы закрепить знания","truth":true,"first":"П"},{"term":"Инновация (innovation)","real":"Новое решение, которое улучшает продукт, услугу или процесс","shown":"Доля дохода, которая уходит на платежи по кредитам","truth":false,"first":"И"},{"term":"Инфляция","real":"Общий рост цен","shown":"Общий рост цен","truth":true,"first":"И"},{"term":"Зарплата на руки","real":"Начисленная зарплата минус ОПВ и ИПН","shown":"Новое решение, которое улучшает продукт, услугу или процесс","truth":false,"first":"З"},{"term":"Сложный процент","real":"Начисление процентов на проценты","shown":"Начисление процентов на проценты","truth":true,"first":"С"},{"term":"Долговая нагрузка","real":"Доля дохода, которая уходит на платежи по кредитам","shown":"Начисленная зарплата минус ОПВ и ИПН","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Повторение (review)","def":"Возвращение к изученному, чтобы закрепить знания"},{"term":"Инновация (innovation)","def":"Новое решение, которое улучшает продукт, услугу или процесс"},{"term":"Инфляция","def":"Общий рост цен"},{"term":"Зарплата на руки","def":"Начисленная зарплата минус ОПВ и ИПН"},{"term":"Сложный процент","def":"Начисление процентов на проценты"},{"term":"Долговая нагрузка","def":"Доля дохода, которая уходит на платежи по кредитам"},{"term":"Прибыль","def":"Выручка минус затраты"}],"english":"innovation — инновация; review — повторение","concepts":{"head":"Базовые понятия","items":["Бизнес — деятельность ради прибыли через решение проблем клиента.","Инновация (innovation) — новое решение, которое делает продукт лучше.","Прибыль = выручка − затраты.","Инфляция — рост цен.","Зарплата на руки = начислено − ОПВ 10% − ИПН 10% с учётом вычета 30 МРП (129 750 тенге).","Сложный процент: S × (1 + r)ⁿ.","Переплата = всего выплачено − кредит.","Гарантия КФГД — сберегательные вклады в тенге до 20 млн тенге."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитать все задания и начать с лёгких","В тесте выбрать один ответ","В практическом задании записать данные, формулу, расчёт и ответ с единицами","Оставить 4 минуты на самопроверку"]},"scheme":"«карта полугодия»: в центре «Бизнес и финансы», лучи — «Бизнес-идея и клиент», «Инфляция», «Зарплата и налоги», «Банк: вклад, карта, кредит», «Страхование», «Мошенничество», «Ярмарка и прибыль».","examples":[{"lab":"Казахстанский","text":"Продавец в Семее, начислено 200 000 тенге: ОПВ 20 000, ИПН (200 000 − 20 000 − 129 750) × 10% = 5 025, на руки 174 975 тенге."},{"lab":"Второй пример","text":"Цена 50 000 тенге при инфляции 8% через 2 года: 50 000 × 1,08² = 58 320 тенге."}],"mistake":{"myth":"Ответ без единиц измерения и без хода решения","fix":"Баллы ставятся и за решение."},"check":[{"q":"Чем выручка отличается от прибыли?","a":"Прибыль — после вычета затрат"},{"q":"С какой суммы считается ИПН?","a":"Начислено − ОПВ − вычет"},{"q":"Что делает КФГД?","a":"Возвращает вклады при закрытии банка"}],"kz":{"text":"Национальный банк Казахстана выпускает памятные монеты и банкноты, а тенге, введённый 15 ноября 1993 года, — символ экономической самостоятельности страны.","link":"почти все задачи полугодия решаются в тенге и опираются на казахстанские правила (ИПН, ОПВ, КФГД)."},"world":{"text":"Во многих странах школьники в конце полугодия выполняют итоговые работы, а исследования ОЭСР (PISA) сравнивают финансовую грамотность подростков разных стран. Это связано с ЦУР ООН 4 «Качественное образование».","link":""},"fact":"Слово «экзамен» происходит от латинского examen — «стрелка весов», то есть экзамен буквально «взвешивает» знания. Первые государственные экзамены для отбора чиновников появились в Китае более тысячи лет назад.","cards":[{"n":"1","title":"Тест (по 1 баллу)","lines":["1) Прибыль — это: а) все деньги от продаж; б) выручка минус затраты; в) деньги в банке.","2) Инфляция — это: а) рост общего уровня цен; б) рост зарплаты; в) снижение налогов.","3) ОПВ работника составляют: а) 3,5%; б) 10%; в) 16%.","4) Базовый вычет по ИПН в месяц: а) 30 МРП; б) 10 МРП; в) нет вычета.","5) Капитализация — это: а) снятие процентов; б) добавление процентов к вкладу; в) комиссия банка.","6) КФГД гарантирует сберегательные вклады в тенге до: а) 1 млн; б) 20 млн; в) без ограничения.","7) Франшиза — это: а) часть ущерба, которую платит клиент; б) цена полиса; в) бонус.","8) Банк просит код из SMS по телефону — это: а) нормально; б) признак мошенничества.","9) Дроппер — это: а) владелец карты, через которую проводят украденные деньги; б) кассир.","10) Инновация — это: а) копия товара; б) новое решение, улучшающее продукт."],"hand":"Сдать: бланк ответов.","answers":[["1","Б"],["2","А"],["3","Б"],["4","А"],["5","Б"],["6","Б"],["7","А"],["8","Б"],["9","А"],["10","Б"]]},{"n":"2","title":"Практическое задание (10 баллов)","lines":["Герой: Аружан, начислено 250 000 условных тенге в месяц.","1) Рассчитайте зарплату на руки (ОПВ 10%, вычет 129 750, ИПН 10%).","2) Она откладывает 50 000 в месяц на цель 550 000. Через сколько месяцев накопит?","3) Цена цели растёт на 6% в год. Сколько цель будет стоить через год?","4) Магазин предлагает рассрочку под видом кредита: 12 платежей по 52 000. Найдите переплату и долговую нагрузку от зарплаты на руки."],"hand":"Сдать: решения с ходом расчёта.","answers":[["1","ОПВ 25 000; ИПН 9 525; на руки 215 475."],["2","11 месяцев."],["3","583 000."],["4","Переплата 74 000; нагрузка ≈ 24%."]]},{"n":"3","title":"Чек-лист самопроверки","lines":["Ответил на все 10 вопросов.","В каждом расчёте есть формула.","У ответов есть единицы (тенге, %, месяцы).","Проверил вычитание вычета в ИПН.","Ответ правдоподобен."],"hand":"Сдать: вместе с работой.","answers":[]}],"homework":"Запиши 2 темы полугодия, в которых ты уверен, и 1 тему, которую хочешь разобрать на следующем уроке, с вопросом к тренеру.","support":"Увеличенный шрифт, справочная строка с формулами в начале практического задания (без ответов), дополнительные 3 минуты при необходимости.","advanced":"Дополнительное задание: оценить, вырастет ли покупательная способность вклада 100 000 тенге под условные 10% с капитализацией через 2 года при инфляции 7% (100 000 × 1,21 = 121 000; цены × 1,1449; 121 000 ÷ 1,1449 ≈ 105 686 — да).","photo":{"src":"lessons/img/09_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие темы полугодия пригодятся вам в любой стране мира?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l30.pptx","name":"30. Итоговая работа за полугодие — все разделы (9 кл).pptx","mb":1.4}},{"id":"09_31","g":9,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Все разделы","format":"Итоговая работа","skills":["Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет найти и классифицировать свои ошибки в итоговой работе, исправить их с объяснением и составить личный план устранения пробелов.","criteria":["Я нахожу каждую свою ошибку и определяю её тип.","Я исправляю ошибку и объясняю правило своими словами.","Я принимаю обратную связь тренера и составляю план из 2 конкретных шагов."],"result":"Лист работы над ошибками: таблица «ошибка — тип — правильное решение — правило», исправленное практическое задание и личный план из 2 шагов.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ошибка (mistake)","real":"Неверный ответ или шаг решения, который показывает, что нужно повторить","shown":"Неверный ответ или шаг решения, который показывает, что нужно повторить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Конкретный комментарий о том, что получилось и что улучшить","shown":"Конкретные шаги, чтобы тема больше не вызывала ошибок","truth":false,"first":"О"},{"term":"Вычислительная ошибка","real":"Правильный ход решения, но неверная арифметика","shown":"Правильный ход решения, но неверная арифметика","truth":true,"first":"В"},{"term":"Понятийная ошибка","real":"Неверное понимание термина или правила","shown":"Конкретный комментарий о том, что получилось и что улучшить","truth":false,"first":"П"},{"term":"Ошибка невнимательности","real":"Неправильно прочитано условие","shown":"Неправильно прочитано условие","truth":true,"first":"О"},{"term":"План устранения пробелов","real":"Конкретные шаги, чтобы тема больше не вызывала ошибок","shown":"Неверное понимание термина или правила","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный ответ или шаг решения, который показывает, что нужно повторить"},{"term":"Обратная связь (feedback)","def":"Конкретный комментарий о том, что получилось и что улучшить"},{"term":"Вычислительная ошибка","def":"Правильный ход решения, но неверная арифметика"},{"term":"Понятийная ошибка","def":"Неверное понимание термина или правила"},{"term":"Ошибка невнимательности","def":"Неправильно прочитано условие"},{"term":"План устранения пробелов","def":"Конкретные шаги, чтобы тема больше не вызывала ошибок"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Определения","items":["Ошибка (mistake) — не провал, а сигнал, что нужно доучить.","Обратная связь (feedback) помогает понять, что именно исправить.","Ошибки бывают трёх типов: вычислительные, понятийные и ошибки невнимательности."]},"steps":{"head":"Как работать над ошибками, по шагам","items":["Найти задание с потерянными баллами","Определить тип ошибки","Найти правило в конспекте","Решить заново с полным ходом решения","Записать правило своими словами","Решить похожую задачу для закрепления"]},"scheme":"Три корзины «Считаю», «Понимаю», «Читаю» (вычислительные, понятийные, невнимательность); ученики ставят стикеры со своими ошибками в нужную корзину — видно, какие темы повторить всему классу.","examples":[{"lab":"Казахстанский","text":"Ученик считал ИПН с начисленных 250 000 тенге без ОПВ и вычета и получил 25 000 вместо 9 525. Тип — понятийная ошибка. Правило: ИПН = (начислено − ОПВ − 129 750) × 10%."},{"lab":"Второй пример","text":"В задаче о вкладе 80 000 под 10% на 2 года ученик получил 96 000 вместо 96 800 — использовал простой процент вместо капитализации; тоже понятийная ошибка: правило S × (1 + r)ⁿ."}],"mistake":{"myth":"Просто переписать правильный ответ с доски","fix":"Без объяснения правила ошибка повторится."},"check":[{"q":"Какой тип ошибки исправить проще всего?","a":"Вычислительную — проверкой"},{"q":"Почему понятийную ошибку нужно закрепить новой задачей?","a":"Чтобы правило стало своим"},{"q":"Чем полезна обратная связь?","a":"Показывает конкретный следующий шаг"}],"kz":{"text":"Казахстанская компания Kaspi.kz прошла путь от классического банка к цифровой платформе с платежами, маркетплейсом и госуслугами; такое развитие невозможно без постоянных обновлений приложения, исправления ошибок и учёта отзывов клиентов.","link":"работа над ошибками и обратная связь — основа развития бизнеса."},"world":{"text":"Культура анализа ошибок есть в авиации: международные правила требуют расследовать каждый инцидент, чтобы ошибка не повторилась, и это сделало авиаперевозки одним из самых безопасных видов транспорта.","link":""},"fact":"Томасу Эдисону приписывают слова о том, что он не терпел неудач, а нашёл тысячи способов, которые не работают, — речь о поиске материала для нити лампы накаливания. Точная формулировка цитаты спорна, но сам долгий перебор материалов документально подтверждён.","cards":[{"n":"1","title":"Работа над ошибками","lines":["Таблица: № задания | Мой ответ | Тип ошибки (считаю / понимаю / читаю) | Правильное решение | Правило своими словами.","Внизу: «Мой план: 1) … 2) …»."],"hand":"Сдать: заполненную таблицу.","answers":[]},{"n":"2","title":"Задачи на закрепление","lines":["1) ИПН: начислено 180 000 тенге. Найдите зарплату на руки. (ОПВ 18 000; облагаемый 32 250; ИПН 3 225; на руки 158 775.)","2) Вклад: 60 000 под условные 10% с капитализацией на 2 года. (72 600.)","3) Инфляция: цена 30 000, инфляция 5% в год, 2 года. (33 075.)","4) Кредит: 12 платежей по 18 000 за товар 190 000. Переплата?","5) Невнимательность: «цена выросла на 10%, потом ещё на 10%. На сколько процентов всего?» (21%.)"],"hand":"Сдать: решения в тетради.","answers":[["4","26 000."]]}],"homework":"Выполни свой план: реши 2 задачи по теме, где была ошибка (из Карточки 2 или от тренера), и запиши правило своими словами.","support":"Образец заполненной строки таблицы ошибок; подсказки-правила по каждой теме; консультация с учеником-консультантом.","advanced":"Работа консультантом и составление собственной задачи «с ловушкой» по типичной ошибке класса с ответом.","photo":{"src":"lessons/img/09_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Чему бизнес и школа могут научиться у авиации в работе с ошибками?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (9 кл).pptx","mb":1.3}},{"id":"09_32","g":9,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Все разделы","format":"Деловая игра","skills":["Командная работа","Лидерство","Критическое мышление"],"goal":"К концу урока ученик сможет применить ключевые понятия полугодия в командной игре: решать задачи на прибыль, инфляцию, зарплату, вклады и безопасность и объяснять решения команде.","criteria":["Я правильно решаю задачи раунда и объясняю решение команде.","Я участвую в командных решениях и выполняю свою роль.","Я называю тему, которую закрепил в игре, и что ещё повторить."],"result":"Командный «финансовый баланс» игры: решённые задачи раундов, принятые решения по событиям рынка и итоговый результат с разбором ошибок.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Повторение (review)","real":"Закрепление изученного через применение","shown":"Закрепление изученного через применение","truth":true,"first":"П"},{"term":"Игра (game)","real":"Учебная модель ситуации с правилами, ролями и результатом","shown":"Доля дохода, уходящая на платежи по кредитам","truth":false,"first":"И"},{"term":"Прибыль","real":"Выручка минус затраты","shown":"Выручка минус затраты","truth":true,"first":"П"},{"term":"Инфляция","real":"Общий рост цен","shown":"Учебная модель ситуации с правилами, ролями и результатом","truth":false,"first":"И"},{"term":"Капитализация","real":"Добавление процентов к вкладу","shown":"Добавление процентов к вкладу","truth":true,"first":"К"},{"term":"Долговая нагрузка","real":"Доля дохода, уходящая на платежи по кредитам","shown":"Общий рост цен","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Повторение (review)","def":"Закрепление изученного через применение"},{"term":"Игра (game)","def":"Учебная модель ситуации с правилами, ролями и результатом"},{"term":"Прибыль","def":"Выручка минус затраты"},{"term":"Инфляция","def":"Общий рост цен"},{"term":"Капитализация","def":"Добавление процентов к вкладу"},{"term":"Долговая нагрузка","def":"Доля дохода, уходящая на платежи по кредитам"},{"term":"Узкое место","def":"Этап, который тормозит весь процесс"}],"english":"review — повторение; game — игра","concepts":{"head":"Определения","items":["Игра (game) «Финансовый город» — повторение (review) полугодия: каждая команда — семья предпринимателей с условным капиталом 100 000 тенге.","Чтобы заработать баллы и капитал, нужно верно решать задачи и принимать решения по событиям рынка."]},"steps":{"head":"Как играть, по шагам","items":["Команды получают роли: капитан, финансист, аналитик рисков, спикер","В раунде 1 решают 5 задач (по одной на тему): верный ответ +10 000 к капиталу","В раунде 2 приходят события рынка (инфляция, предложение кредита, мошенник, страховой случай); команда выбирает решение и считает последствия","Разбор — какие решения сработали"]},"scheme":"Табло команд со столбцами «капитал», «баллы раунда 1», «решения раунда 2», «итог»; сбоку «карта тем»: инфляция, зарплата, вклад, кредит, страховка, мошенничество, прибыль.","examples":[{"lab":"Казахстанский","text":"Событие «Поставщик из Шымкента поднял цены на 8%». Затраты команды 40 000 стали 43 200; если не поднять цену, прибыль упадёт на 3 200."},{"lab":"Второй пример","text":"Событие «Вам предлагают вложить 50 000 и через неделю получить 100 000». Верное решение — отказаться: признаки пирамиды; команда, которая «вложилась», теряет 50 000."}],"mistake":{"myth":"Решать быстро ради баллов и не проверять признаки риска","fix":"Разбираем на событии с пирамидой."},"check":[{"q":"Что выгоднее при инфляции 8% — держать капитал наличными или на вкладе под условные 10%?","a":"На вкладе"},{"q":"Как посчитать прибыль после роста затрат?","a":"Выручка − новые затраты"},{"q":"Почему отказ от «выгодного предложения» иногда лучшее решение?","a":"Признаки мошенничества"}],"kz":{"text":"Казахстанская национальная игра «тоғызқұмалақ» (тогыз кумалак) — стратегическая игра на счёт и планирование ходов, которую называют «гимнастикой ума».","link":"как и в финансовой игре, важно считать и думать на несколько ходов вперёд."},"world":{"text":"Игровые симуляции используют для обучения в разных странах: например, игра Monopoly изначально была создана Элизабет Мэги как «The Landlord’s Game», чтобы показать экономические проблемы.","link":""},"fact":"Игра Monopoly восходит к «The Landlord’s Game», которую Элизабет Мэги запатентовала в 1904 году, чтобы показать, как монополии концентрируют богатство. Позже игру переработали и выпустили массовым тиражом в 1935 году.».)","cards":[{"n":"1","title":"Правила «Финансового города»","lines":["Старт: 100 000 условных тенге на команду. Роли: капитан (решает спорные вопросы), финансист (считает), аналитик рисков (проверяет признаки мошенничества), спикер (объявляет решения).","Раунд 1: верный ответ +10 000.","Раунд 2: последствия решений по событиям. Бонус «помощь соседу» +5 000 один раз."],"hand":"Сдать: не нужно.","answers":[]},{"n":"2","title":"Задачи раунда 1","lines":["1) Выручка 60 000, затраты 38 000. Прибыль?","2) Цена 20 000, инфляция 5%, 2 года. (22 050.)","3) Начислено 200 000. На руки?","4) Вклад 50 000 под условные 10% с капитализацией, 2 года. (60 500.)","5) Кредит 100 000, 12 платежей по 9 500. Переплата?"],"hand":"Сдать: ответы команды.","answers":[["1","22 000."],["3","174 975."],["5","14 000."]]},{"n":"3","title":"События раунда 2","lines":["1) «Поставщик поднял цены на 8%: затраты 40 000». Решение: поднять цену или сократить затраты. (Рост затрат 3 200.)","2) «Инфляция 8%: что сделать с 50 000 свободных денег — оставить наличными или на вклад под условные 10%?» (Вклад: +5 000 к капиталу; наличные: −4 000 покупательной способности.)","3) «Звонок: „Банк, назовите код“». (Отказ: 0; согласие: −30 000.)","4) «Предложение: вложи 50 000 — получи 100 000 через неделю». (Отказ: 0; вложение: −50 000.)","5) «Сломалось оборудование, ущерб 30 000. Если брали страховку за 3 000 с франшизой 5 000 — выплата 25 000»."],"hand":"Сдать: решения команды на табло.","answers":[]}],"homework":"Составь 3 вопроса для игры-викторины по теме полугодия, где ты раньше ошибался, с правильными ответами и объяснениями.","support":"Памятка с формулами полугодия у каждой команды; роль «финансиста» дополняется помощником.","advanced":"Роль «рыночного аналитика»: предсказать, как событие повлияет на капитал всех команд, и предложить лучшую стратегию.","photo":{"src":"lessons/img/09_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Чему игра может научить лучше, чем лекция, и где её модель упрощает реальность?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g09-l32.pptx","name":"32. Игра-повторение по темам полугодия (9 кл).pptx","mb":1.5}}];
